-- ============================================================
-- O Livro dos Espiritos — questoes 841 a 1019
-- Allan Kardec, traducao de Guillon Ribeiro (dominio publico).
-- Entram como RASCUNHO: nao aparecem no site ate serem publicadas.
-- Pode rodar mais de uma vez — atualiza em vez de duplicar.
-- ============================================================

on conflict (numero) do update
  set parte = excluded.parte,
      capitulo = excluded.capitulo,
      pergunta = excluded.pergunta,
      resposta = excluded.resposta;

select count(*) as questoes_cadastradas,
       count(*) filter (where status = 'rascunho') as em_rascunho
from public.questoes;
