insert into public.questoes (numero, parte, capitulo, pergunta, resposta, status)
values
  (841, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Para respeitar a liberdade de consciência, dever-se-á deixar que se propaguem doutrinas perniciosas, ou poder-se-á, sem atentar contra aquela liberdade, procurar trazer ao caminho da verdade os que se transviaram obedecendo a falsos princípios?', 'Certamente que podeis e até deveis; mas, ensinai, a exemplo de Jesus, servindo-vos da brandura e da persuasão e não da força, o que seria pior do que a crença daquele a quem desejaríeis convencer. Se alguma coisa se pode impor, é o bem e a fraternidade. Mas não cremos que o melhor meio de fazê-los admitidos seja obrar com violência. A convicção não se impõe.', 'rascunho'),
  (842, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Por que indícios se poderá reconhecer, entre todas as doutrinas que alimentam a pretensão de ser a expressão única da verdade, a que tem o direito de se apresentar como tal?', 'Será aquela que mais homens de bem e menos hipócritas fizer, isto é, pela prática da lei de amor na sua maior pureza e na sua mais ampla aplicação. Esse o sinal por que reconhecereis que uma doutrina é boa, visto que toda doutrina que tiver por efeito semear a desunião e estabelecer uma linha de separação entre os filhos de Deus não pode deixar de ser falsa e perniciosa.', 'rascunho'),
  (843, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Tem o homem o livre-arbítrio de seus atos?', 'Pois que tem a liberdade de pensar, tem igualmente a de obrar. Sem o livre-arbítrio, o homem seria máquina.', 'rascunho'),
  (844, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Do livre-arbítrio goza o homem desde o seu nascimento?', 'Há liberdade de agir, desde que haja vontade de fazê-lo. Nas primeiras fases da vida, quase nula é a liberdade, que se desenvolve e muda de objeto com o desenvolvimento das faculdades. Estando seus pensamentos em concordância com o que a sua idade reclama, a criança aplica o seu livre--arbítrio àquilo que lhe é necessário.', 'rascunho'),
  (845, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Não constituem obstáculos ao exercício do livre-arbítrio as predisposições instintivas que o homem já traz consigo ao nascer?', 'As predisposições instintivas são as do Espírito antes de encarnar. Conforme seja este mais ou menos adiantado, elas podem arrastá-lo à prática de atos repreensíveis, no que será secundado pelos Espíritos que simpatizam com essas disposições. Não há, porém, arrastamento irresistível, uma vez que se tenha a vontade de resistir. Lembrai-vos de que querer é poder.', 'rascunho'),
  (846, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Sobre os atos da vida nenhuma influência exerce o organismo? E, se essa influência existe, não será exercida com prejuízo do livre-arbítrio? 268 – Allan Kar dec', 'É inegável que sobre o Espírito exerce influência a matéria, que pode embaraçar-lhe as manifestações. Daí vem que, nos mundos onde os corpos são menos materiais do que na Terra, as faculdades se desdobram mais livremente. Porém, o instrumento não dá a faculdade. Além disso, cumpre se distingam as faculdades morais das intelectuais. Tendo um homem o instinto do assassínio, seu próprio Espírito é, indubitavelmente, quem possui esse instinto e quem lho dá; não são seus órgãos que lho dão. Semelhante ao bruto, e ainda pior do que este, se torna aquele que nulifica o seu pensamento, para só se ocupar com a matéria, pois que não cuida mais de se premunir contra o mal. Nisto é que incorre em falta, porquanto assim procede por vontade sua." (Vede Nº 367 e seguintes — "Influência do organismo".)', 'rascunho'),
  (847, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'A aberração das faculdades tira ao homem o livre--arbítrio?', 'Já não é senhor do seu pensamento aquele cuja inteligência se ache turbada por uma causa qualquer e, desde então, já não tem liberdade. Essa aberração constitui muitas vezes uma punição para o Espírito que, porventura, tenha sido, noutra existência, fútil e orgulhoso, ou tenha feito mau uso de suas faculdades. Pode esse Espírito, em tal caso, renascer no corpo de um idiota, como o déspota no de um escravo e o mau rico no de um mendigo. O Espírito, porém, sofre por efeito desse constrangimento, de que tem perfeita consciência. Está aí a ação da matéria." (371 e seguintes)', 'rascunho'),
  (848, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Servirá de escusa aos atos reprováveis o ser devida à embriaguez a aberração das faculdades intelectuais?', 'Não, porque foi voluntariamente que o ébrio se privou da sua razão, para satisfazer a paixões brutais. Em vez de uma falta, comete duas.', 'rascunho'),
  (849, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Qual a faculdade predominante no homem em estado de selvageria: o instinto, ou o livre-arbítrio?', 'O instinto, o que não o impede de agir com inteira liberdade, no tocante a certas coisas. Mas, aplica, como a criança, essa liberdade às suas necessidades e ela se amplia com a inteligência. Conseguintemente, tu, que és mais esclarecido do que um selvagem, também és mais responsável pelo que fazes do que um selvagem o é pelos seus atos.', 'rascunho'),
  (850, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'A posição social não constitui às vezes, para o homem, obstáculo à inteira liberdade de seus atos?', 'É fora de dúvida que o mundo tem suas exigências. Deus é justo e tudo leva em conta. Deixa-vos, entretanto, a responsabilidade de nenhum esforço empregardes para vencer os obstáculos.', 'rascunho'),
  (851, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Haverá fatalidade nos acontecimentos da vida, conforme ao sentido que se dá a este vocábulo? Quer dizer: todos os acontecimentos são predeterminados? E, neste caso, que vem a ser do livre-arbítrio?', 'A fatalidade existe unicamente pela escolha que o Espírito fez, ao encarnar, desta ou daquela prova para sofrer. Escolhendo-a, instituiu para si uma espécie de destino, que é a conseqüência mesma da posição em que vem a achar-se colocado. Falo das provas físicas, pois, pelo que toca às provas morais e às tentações, o Espírito, conservando o livre-arbítrio quanto ao bem e ao mal, é sempre senhor de ceder ou de resistir. Ao vê-lo fraquear, um bom Espírito pode vir-lhe em auxílio, mas não pode influir sobre ele de maneira a dominar-lhe a vontade. Um Espírito mau, isto é, inferior, mostrando-lhe, exagerando aos seus olhos um perigo físico, o poderá abalar e amedrontar. Nem por isso, entretanto, a vontade do Espírito encarnado deixa de se conservar livre de quaisquer peias.', 'rascunho'),
  (852, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Há pessoas que parecem perseguidas por uma fatalidade, independente da maneira por que procedem. Não lhes estará no destino o infortúnio?', 'São, talvez, provas que lhes caiba sofrer e que elas escolheram. Porém, ainda aqui lançais à conta do destino o que as mais das vezes é apenas conseqüência de vossas próprias faltas. Trata de ter pura a consciência em meio dos males que te afligem e já bastante consolado te sentirás." As idéias exatas ou falsas que fazemos das coisas nos levam a ser bem ou malsucedidos, de acordo com o nosso caráter e a nossa posição social. Achamos mais simples e menos humilhante para o nosso amor-próprio atribuir antes à sorte ou ao destino os insucessos que experimentamos, do que à nossa própria falta. É certo que para isso contribui algumas vezes a influência dos Espíritos, mas também o é que podemos sempre forrar-nos a essa influência, repelindo as idéias que eles nos sugerem, quando más.', 'rascunho'),
  (853, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Algumas pessoas só escapam de um perigo mortal para cair em outro. Parece que não podiam escapar da morte. Não há nisso fatalidade?', 'Fatal, no verdadeiro sentido da palavra, só o instante da morte o é. Chegado esse momento, de uma forma ou doutra, a ele não podeis furtar-vos." a) — Assim, qualquer que seja o perigo que nos ameace, se a hora da morte ainda não chegou, não morreremos? "Não; não perecerás e tens disso milhares de exemplos. Quando, porém, soe a hora da tua partida, nada poderá impedir que partas. Deus sabe de antemão de que gênero será a morte do homem e muitas vezes seu Espírito também o sabe, por lhe ter sido isso revelado, quando escolheu tal ou qual existência.', 'rascunho'),
  (854, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Do fato de ser infalível a hora da morte, poder-se-á deduzir que sejam inúteis as precauções que tomemos para evitá-la?', 'Não, visto que as precauções que tomais vos são sugeridas com o fito de evitardes a morte que vos ameaça. São um dos meios empregados para que ela não se dê.', 'rascunho'),
  (855, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Com que fim nos faz a Providência correr perigos que nenhuma conseqüência devem ter?', 'O fato de ser a tua vida posta em perigo constitui um aviso que tu mesmo desejaste, a fim de te desviares do mal e te tornares melhor. Se escapas desse perigo, quando ainda sob a impressão do risco que correste, cogitas, mais ou menos 270 – Allan Kar dec seriamente, de te melhorares, conforme seja mais ou menos forte sobre ti a influência dos Espíritos bons. Sobrevindo o mau Espírito (digo mau, subentendendo o mal que ainda existe nele), entras a pensar que do mesmo modo escaparás a outros perigos e deixas que de novo tuas paixões se desencadeiem. Por meio dos perigos que correis, Deus vos lembra a vossa fraqueza e a fragilidade da vossa existência. Se examinardes a causa e a natureza do perigo, verificareis que, quase sempre, suas conseqüências teriam sido a punição de uma falta cometida ou da negligência no cumprimento de um dever. Deus, por essa forma, exorta o Espírito a cair em si e a se emendar." (526-532)', 'rascunho'),
  (856, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Sabe o Espírito antecipadamente de que gênero será sua morte?', 'Sabe que o gênero de vida que escolheu o expõe mais a morrer desta do que daquela maneira. Sabe igualmente quais as lutas que terá de sustentar para evitá- lo e que, se Deus o permitir, não sucumbirá.', 'rascunho'),
  (857, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Há homens que afrontam os perigos dos combates, persuadidos, de certo modo, de que a hora não lhes chegou. Haverá algum fundamento para essa confiança?', 'Muito amiúde tem o homem o pressentimento do seu fim, como pode ter o de que ainda não morrerá. Esse pressentimento lhe vem dos Espíritos seus protetores, que assim o advertem para que esteja pronto a partir, ou lhe fortalecem a coragem nos momentos em que mais dela necessita. Pode vir-lhe também da intuição que tem da existência que escolheu, ou da missão que aceitou e que sabe ter que cumprir." (411-522)', 'rascunho'),
  (858, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Por que razão os que pressentem a morte a temem geralmente menos do que os outros?', 'Quem teme a morte é o homem, não o Espírito. Aquele que a pressente pensa mais como Espírito do que como homem. Compreende ser ela a sua libertação e espera-a.', 'rascunho'),
  (859, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Com todos os acidentes, que nos sobrevêm no curso da vida, se dá o mesmo que com a morte, que não pode ser evitada, quando tem de ocorrer?', 'São de ordinário coisas muito insignificantes, de sorte que vos podemos prevenir deles e fazer que os eviteis algumas vezes, dirigindo o vosso pensamento, pois nos desagradam os sofrimentos materiais. Isso, porém, nenhuma importância tem na vida que escolhestes. A fatalidade, verdadeiramente, só existe quanto ao momento em que deveis aparecer e desaparecer deste mundo." a) — Haverá fatos que forçosamente devam dar-se e que os Espíritos não possam conjurar, embora o queiram? "Há, mas que tu viste e pressentiste quando, no estado de Espírito, fizeste a tua escolha. Não creias, entretanto, que tudo o que sucede esteja escrito, como costumam dizer. Um acontecimento qualquer pode ser a conseqüência de um ato que praticaste por tua livre vontade, de tal sorte que, se não o houvesses praticado, o acontecimento não se teria dado. Imagina que queimas o dedo. Isso nada mais é senão resultado da tua imprudência e efeito da matéria. Só as grandes dores, os fatos importantes e capazes de influir no moral, Deus os prevê, porque são úteis à tua depuração e à tua instrução.', 'rascunho'),
  (860, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Pode o homem, pela sua vontade e por seus atos, fazer que se não dêem acontecimentos que deveriam verificar-se e reciprocamente?', 'Pode-o, se essa aparente mudança na ordem dos fatos tiver cabimento na seqüência da vida que ele escolheu. Acresce que, para fazer o bem, como lhe cumpre, pois que isso constitui o objetivo único da vida, facultado lhe é impedir o mal, sobretudo aquele que possa concorrer para a produção de um mal maior.', 'rascunho'),
  (861, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Ao escolher a sua existência, o Espírito daquele que comete um assassínio sabia que viria a ser assassino?', 'Não. Escolhendo uma vida de lutas, sabe que terá ensejo de matar um de seus semelhantes, mas não sabe se o fará, visto que ao crime precederá quase sempre, de sua parte, a deliberação de praticá-lo. Ora, aquele que delibera sobre uma coisa é sempre livre de fazê-la, ou não. Se soubesse previamente que, como homem, teria que cometer um crime, o Espírito estaria a isso predestinado. Ficai, porém, sabendo que ninguém há predestinado ao crime e que todo crime, como qualquer outro ato, resulta sempre da vontade e do livre-arbítrio." "Demais, sempre confundis duas coisas muito distintas: os sucessos materiais da vida e os atos da vida moral. A fatalidade, que algumas vezes há, só existe com relação àqueles sucessos materiais, cuja causa reside fora de vós e que independem da vossa vontade. Quanto aos atos da vida moral, esses emanam sempre do próprio homem que, por conseguinte, tem sempre a liberdade de escolher. No tocante, pois, a esses atos, nunca há fatalidade.', 'rascunho'),
  (862, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Pessoas existem que nunca logram bom êxito em coisa alguma, que parecem perseguidas por um mau gênio em todos os seus empreendimentos. Não se pode chamar a isso fatalidade?', 'Será uma fatalidade, se lhe quiseres dar esse nome, mas que decorre do gênero da existência escolhida. É que essas pessoas quiseram ser provadas por uma vida de decepções, a fim de exercitarem a paciência e a resignação. Entretanto, não creias seja absoluta essa fatalidade. Resulta muitas vezes do caminho falso que tais pessoas tomam, em discordância com suas inteligências e aptidões. Grandes probabilidades tem de se afogar quem pretender atravessar a nado um rio, sem saber nadar. O mesmo se dá relativamente à maioria dos acontecimentos da vida. Quase sempre obteria o homem bom êxito, se só tentasse o que estivesse em relação com as suas faculdades. O que o perde são o seu amor-próprio e a sua ambição, que o desviam da senda que lhe é própria e o fazem considerar vocação o que não passa de desejo de satisfazer a certas paixões. Fracassa por sua culpa. Mas, em vez de culpar- se a si mesmo, prefere queixar-se da sua estrela. Um, por exemplo, que seria bom operário e ganharia honestamente a vida, mete-se a ser mau poeta e morre de fome. Para todos haveria lugar no mundo, desde que cada um soubesse colocar-se no lugar que lhe compete." 272 – Allan Kar dec', 'rascunho'),
  (863, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Os costumes sociais não obrigam muitas vezes o homem a enveredar por um caminho de preferência a outro e não se acha ele submetido à direção da opinião geral, quanto à escolha de suas ocupações? O que se chama respeito humano não constitui óbice ao exercício do livre-arbítrio?', 'São os homens e não Deus quem faz os costumes sociais. Se eles a estes se submetem, é porque lhes convêm. Tal submissão, portanto, representa um ato de livre--arbítrio, pois que, se o quisessem, poderiam libertar-se de semelhante jugo. Por que, então, se queixam? Falece-lhes razão para acusarem os costumes sociais. A culpa de tudo devem lançá-la ao tolo amor-próprio de que vivem cheios e que os faz preferirem morrer de fome a infringi-los. Ninguém lhes leva em conta esse sacrifício feito à opinião pública, ao passo que Deus lhes levará em conta o sacrifício que fizerem de suas vaidades. Não quer isto dizer que o homem deva afrontar sem necessidade aquela opinião, como fazem alguns em quem há mais originalidade do que verdadeira filosofia. Tanto desatino há em procurar alguém ser apontado a dedo, ou considerado animal curioso, quanto acerto em descer voluntariamente e sem murmurar, desde que não possa manter-se no alto da escala.', 'rascunho'),
  (864, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Assim como há pessoas a quem a sorte em tudo é contrária, outras parecem favorecidas por ela, pois que tudo lhes sai bem. A que atribuir isso?', 'De ordinário, é que essas pessoas sabem conduzir-se melhor nas suas empresas. Mas, também pode ser um gênero de prova. O bom êxito as embriaga; fiam-se no seu destino e muitas vezes pagam mais tarde esse bom êxito, mediante revezes cruéis, que a prudência as teria feito evitar.', 'rascunho'),
  (865, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Como se explica que a boa sorte favoreça a algumas pessoas em circunstâncias com as quais nada têm que ver a vontade, nem a inteligência: no jogo, por exemplo?', 'Alguns Espíritos hão escolhido previamente certas espécies de prazer. A fortuna que os favorece é uma tentação. Aquele que, como homem, ganha; perde como Espírito. É uma prova para o seu orgulho e para a sua cupidez.', 'rascunho'),
  (866, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Então, a fatalidade que parece presidir aos destinos materiais de nossa vida também é resultante do nosso livre-arbítrio?', 'Tu mesmo escolheste a tua prova. Quanto mais rude ela for e melhor a suportares, tanto mais te elevarás. Os que passam a vida na abundância e na ventura humana são Espíritos pusilânimes, que permanecem estacionários. Assim, o número dos desafortunados é muito superior ao dos felizes deste mundo, atento que os Espíritos, na sua maioria, procuram as provas que lhes sejam mais proveitosas. Eles vêem perfeitamente bem a futilidade das vossas grandezas e gozos. Acresce que a mais ditosa existência é sempre agitada, sempre perturbada, quando mais não seja, pela ausência da dor." (525 e seguintes)', 'rascunho'),
  (867, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Donde vem a expressão: Nascer sob uma boa estrela?', 'Antiga superstição, que prendia às estrelas os destinos dos homens. Alegoria que algumas pessoas fazem a tolice de tomar ao pé da letra.', 'rascunho'),
  (868, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Pode o futuro ser revelado ao homem?', 'Em princípio, o futuro lhe é oculto e só em casos raros e excepcionais permite Deus que seja revelado.', 'rascunho'),
  (869, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Com que fim o futuro se conserva oculto ao homem?', 'Se o homem conhecesse o futuro, negligenciaria do presente e não obraria com a liberdade com que o faz, porque o dominaria a idéia de que, se uma coisa tem que acontecer, inútil será ocupar-se com ela, ou então procuraria obstar a que acontecesse. Não quis Deus que assim fosse, a fim de que cada um concorra para a realização das coisas, até daquelas a que desejaria opor-se. Assim é que tu mesmo preparas muitas vezes os acontecimentos que hão de sobrevir no curso da tua existência.', 'rascunho'),
  (870, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Mas, se convém que o futuro permaneça oculto, por que permite Deus que seja revelado algumas vezes?', 'Permite-o, quando o conhecimento prévio do futuro facilite a execução de uma coisa, em vez de a estorvar, obrigando o homem a agir diversamente do modo por que agiria, se lhe não fosse feita a revelação. Não raro, também é uma prova. A perspectiva de um acontecimento pode sugerir pensamentos mais ou menos bons. Se um homem vem a saber, por exemplo, que vai receber uma herança, com que não conta, pode dar-se que a revelação desse fato desperte nele o sentimento da cobiça, pela perspectiva de se lhe tornarem possíveis maiores gozos terrenos, pela ânsia de possuir mais depressa a herança, desejando talvez, para que tal se dê, a morte daquele de quem herdará. Ou, então, essa perspectiva lhe inspirará bons sentimentos e pensamentos generosos. Se a predição não se cumpre, aí está outra prova, consistente na maneira por que suportará a decepção. Nem por isso, entretanto, lhe caberá menos o mérito ou o demérito dos pensamentos bons ou maus que a crença na ocorrência daquele fato lhe fez nascer no íntimo.', 'rascunho'),
  (871, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Pois que Deus tudo sabe, não ignora se um homem sucumbirá ou não em determinada prova. Assim sendo, qual a necessidade dessa prova, uma vez que nada acrescentará ao que Deus já sabe a respeito desse homem?', 'Isso equivale a perguntar por que não criou Deus o homem perfeito e acabado ; por que passa o homem pela infância, antes de chegar à condição de adulto. A prova não tem por fim dar a Deus esclarecimentos sobre o homem, pois que Deus sabe perfeitamente o que ele vale, mas dar ao homem toda a responsabilidade de sua ação, uma vez que tem a liberdade de fazer ou não fazer. Dotado da faculdade de escolher entre o bem e o mal, a prova tem por efeito pô-lo em luta com as tentações do mal e conferir-lhe todo o mérito da resistência. Ora, conquanto saiba de antemão se ele se sairá bem ou não, Deus não o pode, em sua justiça, punir, nem recompensar, por um ato ainda não praticado." Assim sucede entre os homens. Por muito capaz que seja um estudante, por grande que seja a certeza que se tenha de que alcançará bom êxito, ninguém lhe confere grau algum sem exame, isto é, sem prova. Do mesmo modo, o juiz não condena um acusado, senão com 274 – Allan Kar dec fundamento num ato consumado e não na previsão de que ele possa ou deva consumar esse ato. Quanto mais se reflete nas conseqüências que teria para o homem o conhecimento do futuro, melhor se vê quanto foi sábia a Providência em lho ocultar. A certeza de um acontecimento venturoso o lançaria na inação. A de um acontecimento infeliz o encheria de desânimo. Em ambos os casos, suas forças ficariam paralisadas. Daí o não lhe ser mostrado o futuro, senão como meta que lhe cumpre atingir por seus esforços, mas ignorando os trâmites por que terá de passar para alcançá-la. O conhecimento de todos os incidentes da jornada lhe tolheria a iniciativa e o uso do livre-arbítrio. Ele se deixaria resvalar pelo declive fatal dos acontecimentos, sem exercer suas faculdades. Quando o feliz êxito de uma coisa está assegurado, ninguém mais com ela se preocupa.', 'rascunho'),
  (872, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'A questão do livre-arbítrio se pode resumir assim: O homem não é fatalmente levado ao mal; os atos que pratica não foram previamente determinados; os crimes que comete não resultam de uma sentença do destino. Ele pode, por prova e por expiação, escolher uma existência em que seja arrastado ao crime, quer pelo meio onde se ache colocado, quer pelas circunstâncias que sobrevenham, mas será sempre livre de agir ou não agir. Assim, o livre-arbítrio existe para ele, quando no estado de Espírito, ao fazer a escolha da existência e das provas e, como encarnado, na faculdade de ceder ou de resistir aos arrastamentos a que todos nos temos voluntariamente submetido. Cabe à educação combater essas más tendências. Fá-lo-á utilmente, quando se basear no estudo aprofundado da natureza moral do homem. Pelo conhecimento das leis que regem essa natureza moral, chegar-se-á a modificá-la, como se modifica a inteligência pela instrução e o temperamento pela higiene. Desprendido da matéria e no estado de erraticidade, o Espírito procede à escolha de suas futuras existências corporais, de acordo com o grau de perfeição a que haja chegado e é nisto, como temos dito, que consiste sobretudo o seu livre- arbítrio. Esta liberdade, a encarnação não a anula. Se ele cede à influência da matéria, é que sucumbe nas provas que por si mesmo escolheu. Para ter quem o ajude a vencê-las, concedido lhe é invocar a assistência de Deus e dos bons Espíritos. Sem o livre-arbítrio, o homem não teria nem culpa por praticar o mal, nem mérito em praticar o bem. E isto a tal ponto está reconhecido que, no mundo, a censura ou o elogio são feitos à intenção, isto é, à vontade. Ora, quem diz vontade diz liberdade. Nenhuma desculpa poderá, portanto, o homem buscar, para os seus delitos, na sua organização física, sem abdicar da razão e da sua condição de ser humano, para se equiparar ao bruto. Se fora assim quanto ao mal, assim não poderia deixar de ser relativamente ao bem. Mas, quando o homem pratica o bem, tem grande cuidado de averbar o fato à sua conta, como mérito, e não cogita de por ele gratificar os seus órgãos, o que prova que, por instinto, não renuncia, malgrado à opinião de alguns sistemáticos, ao mais belo privilégio de sua espécie: a liberdade de pensar. A fatalidade, como vulgarmente é entendida, supõe a decisão prévia e irrevogável de todos os sucessos da vida, qualquer que seja a importância deles. Se tal fosse a ordem das coisas, o homem seria qual máquina sem vontade. De que lhe serviria a inteligência, desde que houvesse de estar invariavelmente dominado, em todos os seus atos, pela força do destino? Semelhante doutrina, se verdadeira, conteria a destruição de toda liberdade moral; já não haveria para o homem responsabilidade, nem, por conseguinte, bem, nem mal, crimes ou virtudes. Não seria possível que Deus, soberanamente justo, castigasse suas criaturas por faltas cujo cometimento não dependera delas, nem que as recompensasse por virtudes de que nenhum mérito teriam. Demais, tal lei seria a negação da do progresso, porquanto o homem, tudo esperando da sorte, nada tentaria para melhorar a sua posição, visto que não conseguiria ser mais nem menos. Contudo, a fatalidade não é uma palavra vã. Existe na posição que o homem ocupa na Terra e nas funções que aí desempenha, em conseqüência do gênero de vida que seu Espírito escolheu como prova, expiação ou missão. Ele sofre fatalmente todas as vicissitudes dessa existência e todas as tendências boas ou más, que lhe são inerentes. Aí, porém, acaba a fatalidade, pois da sua vontade depende ceder ou não a essas tendências. Os pormenores dos acontecimentos, esses ficam subordinados às circunstâncias que ele próprio cria pelos seus atos, sendo que nessas circunstâncias podem os Espíritos influir pelos pensamentos que sugiram. Há fatalidade, portanto, nos acontecimentos que se apresentam, por serem estes conseqüência da escolha que o Espírito fez da sua existência de homem. Pode deixar de haver fatalidade no resultado de tais acontecimentos, visto ser possível ao homem, pela sua prudência, modificar-lhes o curso. Nunca há fatalidade nos atos da vida moral. No que concerne à morte é que o homem se acha submetido, em absoluto, à inexorável lei da fatalidade, por isso que não pode escapar à sentença que lhe marca o termo da existência, nem ao gênero de morte que haja de cortar a esta o fio. Segundo a doutrina vulgar, de si mesmo tiraria o homem todos os seus instintos, que, então, proviriam, ou da sua organização física, pela qual nenhuma responsabilidade lhe toca, ou da sua própria natureza, caso em que lícito lhe fora procurar desculpar-se consigo mesmo, dizendo não lhe pertencer a culpa de ser feito como é. Muito mais moral se mostra, indiscutivelmente, a Doutrina Espírita. Ela admite no homem o livre-arbítrio em toda a sua plenitude e, se lhe diz que, praticando o mal, ele cede a uma sugestão estranha e má, em nada lhe diminui a responsabilidade, pois lhe reconhece o poder de resistir, o que evidentemente lhe é muito mais fácil do que lutar contra a sua própria natureza. Assim, de acordo com a Doutrina Espírita, não há arrastamento irresistível: o homem pode sempre cerrar ouvidos à voz oculta que lhe fala no íntimo, induzindo-o ao mal, como pode cerrá- los à voz material daquele que lhe fale ostensivamente. Pode-o pela ação da sua vontade, pedindo a Deus a força necessária e reclamando, para tal fim, a assistência dos bons Espíritos. Foi o que Jesus nos ensinou por meio da sublime prece que é a Oração dominical, quando manda que digamos:', 'Não nos deixes sucumbir à tentação, mas livra-nos do mal." Essa teoria da causa determinante dos nossos atos ressalta com evidência de todo o ensino que os Espíritos hão dado. Não só é sublime de moralidade, mas também, acrescentaremos, eleva o homem aos seus próprios olhos. Mostra-o livre 276 – Allan Kar dec de subtrair-se a um jugo obsessor, como livre é de fechar sua casa aos importunos. Ele deixa de ser simples máquina, atuando por efeito de uma impulsão independente da sua vontade, para ser um ente racional, que ouve, julga e escolhe livremente de dois conselhos um. Aditemos que, apesar disto, o homem não se acha privado de iniciativa, não deixa de agir por impulso próprio, pois que, em definitivo, ele é apenas um Espírito encarnado que conserva, sob o envoltório corporal, as qualidades e os defeitos que tinha como Espírito. Conseguintemente, as faltas que cometemos têm por fonte primária a imperfeição do nosso próprio Espírito, que ainda não conquistou a superioridade moral que um dia alcançará, mas que, nem por isso, carece de livre-arbítrio. A vida corpórea lhe é dada para se expungir de suas imperfeições, mediante as provas por que passa, imperfeições que, precisamente, o tornam mais fraco e mais acessível às sugestões de outros Espíritos imperfeitos, que delas se aproveitam para tentar fazê- lo sucumbir na luta em que se empenhou. Se dessa luta sai vencedor, ele se eleva; se fracassa, permanece o que era, nem pior, nem melhor. Será uma prova que lhe cumpre recomeçar, podendo suceder que longo tempo gaste nessa alternativa. Quanto mais se depura, tanto mais diminuem os seus pontos fracos e tanto menos acesso oferece aos que procurem atraí-lo para o mal. Na razão de sua elevação, cresce-lhe a força moral, fazendo que dele se afastem os maus Espíritos. Todos os Espíritos, mais ou menos bons, quando encarnados, constituem a espécie humana e, como o nosso mundo é um dos menos adiantados, nele se conta maior número de Espíritos maus do que de bons. Tal a razão por que aí vemos tanta perversidade. Façamos, pois, todos os esforços para a este planeta não voltarmos, após a presente estada, e para merecermos ir repousar em mundo melhor, em um desses mundos privilegiados, onde não nos lembraremos da nossa passagem por aqui, senão como de um exílio temporário.', 'rascunho'),
  (873, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'O sentimento da justiça está em a natureza, ou é resultado de idéias adquiridas?', 'Está de tal modo em a natureza, que vos revoltais à simples idéia de uma injustiça. É fora de dúvida que o progresso moral desenvolve esse sentimento, mas não o dá. Deus o pôs no coração do homem. Daí vem que, freqüentemente, em homens simples e incultos se vos deparam noções mais exatas da justiça do que nos que possuem grande cabedal de saber.', 'rascunho'),
  (874, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Sendo a justiça uma lei da Natureza, como se explica que os homens a entendam de modos tão diferentes, considerando uns justo o que a outros parece injusto?', 'É porque a esse sentimento se misturam paixões que o alteram, como sucede à maior parte dos outros sentimentos naturais, fazendo que os homens vejam as coisas por um prisma falso.', 'rascunho'),
  (875, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Como se pode definir a justiça?', 'A justiça consiste em cada um respeitar os direitos dos demais." a) — Que é o que determina esses direitos? "Duas coisas: a lei humana e a lei natural. Tendo os homens formulado leis apropriadas a seus costumes e caracteres, elas estabeleceram direitos mutáveis com o progresso das luzes. Vede se hoje as vossas leis, aliás imperfeitas, consagram os mesmos direitos que as da Idade Média. Entretanto, esses direitos antiquados, que agora se vos afiguram monstruosos, pareciam justos e naturais naquela época. Nem sempre, pois, é acorde com a justiça o direito que os homens prescrevem. Demais, 278 – Allan Kar dec este direito regula apenas algumas relações sociais, quando é certo que, na vida particular, há uma imensidade de atos unicamente da alçada do tribunal da consciência.', 'rascunho'),
  (876, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Posto de parte o direito que a lei humana consagra, qual a base da justiça, segundo a lei natural?', 'Disse o Cristo: Queira cada um para os outros o que quereria para si mesmo. No coração do homem imprimiu Deus a regra da verdadeira justiça, fazendo que cada um deseje ver respeitados os seus direitos. Na incerteza de como deva proceder com o seu semelhante, em dada circunstância, trate o homem de saber como quereria que com ele procedessem, em circunstância idêntica. Guia mais seguro do que a própria consciência não lhe podia Deus haver dado." Efetivamente, o critério da verdadeira justiça está em querer cada um para os outros o que para si mesmo quereria e não em querer para si o que quereria para os outros, o que absolutamente não é a mesma coisa. Não sendo natural que haja quem deseje o mal para si, desde que cada um tome por modelo o seu desejo pessoal, é evidente que nunca ninguém desejará para o seu semelhante senão o bem. Em todos os tempos e sob o império de todas as crenças, sempre o homem se esforçou para que prevalecesse o seu direito pessoal. A sublimidade da religião cristã está em que ela tomou o direito pessoal por base do direito do próximo.', 'rascunho'),
  (877, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Da necessidade que o homem tem de viver em sociedade, nascem-lhe obrigações especiais?', 'Certo e a primeira de todas é a de respeitar os direitos de seus semelhantes. Aquele que respeitar esses direitos procederá sempre com justiça. Em o vosso mundo, porque a maioria dos homens não pratica a lei de justiça, cada um usa de represálias. Essa a causa da perturbação e da confusão em que vivem as sociedades humanas. A vida social outorga direitos e impõe deveres recíprocos.', 'rascunho'),
  (878, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Podendo o homem enganar-se quanto à extensão do seu direito, que é o que lhe fará conhecer o limite desse direito?', 'O limite do direito que, com relação a si mesmo, reconhecer ao seu semelhante, em idênticas circunstâncias e reciprocamente." a) — Mas, se cada um atribuir a si mesmo direitos iguais aos de seu semelhante, que virá a ser da subordinação aos superiores? Não será isso a anarquia de todos os poderes? "Os direitos naturais são os mesmos para todos os homens, desde os de condição mais humilde até os de posição mais elevada. Deus não fez uns de limo mais puro do que o de que se serviu para fazer os outros, e todos, aos seus olhos, são iguais. Esses direitos são eternos. Os que o homem estabeleceu perecem com as suas instituições. Demais, cada um sente bem a sua força ou a sua fraqueza e saberá sempre ter uma certa deferência para com os que o mereçam por suas virtudes e sabedoria. É importante acentuar isto, para que os que se julgam superiores conheçam seus deveres, a fim de merecer essas deferências. A subordinação não se achará comprometida, quando a autoridade for deferida à sabedoria.', 'rascunho'),
  (879, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Qual seria o caráter do homem que praticasse a justiça em toda a sua pureza?', 'O do verdadeiro justo, a exemplo de Jesus, porquanto praticaria também o amor do próximo e a caridade, sem os quais não há verdadeira justiça.', 'rascunho'),
  (880, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Qual o primeiro de todos os direitos naturais do homem?', 'O de viver. Por isso é que ninguém tem o de atentar contra a vida de seu semelhante, nem de fazer o que quer que possa comprometer-lhe a existência corporal.', 'rascunho'),
  (881, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'O direito de viver dá ao homem o de acumular bens que lhe permitam repousar quando não mais possa trabalhar?', 'Dá, mas ele deve fazê-lo em família, como a abelha, por meio de um trabalho honesto, e não como egoísta. Há mesmo animais que lhe dão o exemplo de previdência.', 'rascunho'),
  (882, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Tem o homem o direito de defender os bens que haja conseguido juntar pelo seu trabalho?', 'Não disse Deus: ‘Não roubarás?’ E Jesus não disse: ‘Dai a César o que é de César?’ O que, por meio do trabalho honesto, o homem junta constitui legítima propriedade sua, que ele tem o direito de defender, porque a propriedade que resulta do trabalho é um direito natural, tão sagrado quanto o de trabalhar e de viver.', 'rascunho'),
  (883, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'É natural o desejo de possuir?', 'Sim, mas quando o homem deseja possuir para si somente e para sua satisfação pessoal, o que há é egoísmo." a) — Não será, entretanto, legítimo o desejo de possuir, uma vez que aquele que tem de que viver a ninguém é pesado? "Há homens insaciáveis, que acumulam bens sem utilidade para ninguém, ou apenas para saciar suas paixões. Julgas que Deus vê isso com bons olhos? Aquele que, ao contrário, junta pelo trabalho, tendo em vista socorrer os seus semelhantes, pratica a lei de amor e caridade, e Deus abençoa o seu trabalho.', 'rascunho'),
  (884, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Qual o caráter da legítima propriedade?', 'Propriedade legítima só é a que foi adquirida sem prejuízo de outrem." Proibindo-nos que façamos aos outros o que não desejáramos que nos fizessem, a lei de amor e de justiça nos proíbe, ipso facto, a aquisição de bens por quaisquer meios que lhe sejam contrários.', 'rascunho'),
  (885, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Será ilimitado o direito de propriedade? 280 – Allan Kar dec', 'É fora de dúvida que tudo o que legitimamente se adquire constitui uma propriedade. Mas, como havemos dito, a legislação dos homens, porque imperfeita, consagra muitos direitos convencionais, que a lei de justiça reprova. Essa a razão por que eles reformam suas leis, à medida que o progresso se efetua e que melhor compreendem a justiça. O que num século parece perfeito, afigura-se bárbaro no século seguinte.', 'rascunho'),
  (886, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Qual o verdadeiro sentido da palavra caridade, como a entendia Jesus?', 'Benevolência para com todos, indulgência para as imperfeições dos outros, perdão das ofensas." O amor e a caridade são o complemento da lei de justiça, pois amar o próximo é fazer-lhe todo o bem que nos seja possível e que desejáramos nos fosse feito. Tal o sentido destas palavras de Jesus: Amai-vos uns aos outros como irmãos. A caridade, segundo Jesus, não se restringe à esmola, abrange todas as relações em que nos achamos com os nossos semelhantes, sejam eles nossos inferiores, nossos iguais, ou nossos superiores. Ela nos prescreve a indulgência, porque de indulgência precisamos nós mesmos, e nos proíbe que humilhemos os desafortunados, contrariamente ao que se costuma fazer. Apresente-se uma pessoa rica e todas as atenções e deferências lhe são dispensadas. Se for pobre, toda gente como que entende que não precisa preocupar-se com ela. No entanto, quanto mais lastimosa seja a sua posição, tanto maior cuidado devemos pôr em lhe não aumentarmos o infortúnio pela humilhação. O homem verdadeiramente bom procura elevar, aos seus próprios olhos, aquele que lhe é inferior, diminuindo a distância que os separa.', 'rascunho'),
  (887, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Jesus também disse: Amai mesmo os vossos inimigos. Ora, o amor aos inimigos não será contrário às nossas tendências naturais e a inimizade não provirá de uma falta de simpatia entre os Espíritos?', 'Certo ninguém pode votar aos seus inimigos um amor terno e apaixonado. Não foi isso o que Jesus entendeu de dizer. Amar os inimigos é perdoar-lhes e lhes retribuir o mal com o bem. O que assim procede se torna superior aos seus inimigos, ao passo que abaixo deles se coloca, se procura tomar vingança.', 'rascunho'),
  (888, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Que se deve pensar da esmola?', 'Condenando-se a pedir esmola, o homem se degrada física e moralmente: embrutece-se. Uma sociedade que se baseie na lei de Deus e na justiça deve prover à vida do fraco, sem que haja para ele humilhação. Deve assegurar a existência dos que não podem trabalhar, sem lhes deixar a vida à mercê do acaso e da boa vontade de alguns." a) — Dar-se-á reproveis a esmola? "Não; o que merece reprovação não é a esmola, mas a maneira por que habitualmente é dada. O homem de bem, que compreende a caridade de acordo com Jesus, vai ao encontro do desgraçado, sem esperar que este lhe estenda a mão." "A verdadeira caridade é sempre bondosa e benévola; está tanto no ato, como na maneira por que é praticado. Duplo valor tem um serviço prestado com delicadeza. Se o for com altivez, pode ser que a necessidade obrigue quem o recebe a aceitá-lo, mas o seu coração pouco se comoverá." "Lembrai-vos também de que, aos olhos de Deus, a ostentação tira o mérito ao benefício. Disse Jesus: ‘Ignore a vossa mão esquerda o que a direita der.’ Por essa forma, ele vos ensinou a não tisnardes a caridade com o orgulho." "Deve-se distinguir a esmola, propriamente dita, da beneficência. Nem sempre o mais necessitado é o que pede. O temor de uma humilhação detém o verdadeiro pobre, que muita vez sofre sem se queixar. A esse é que o homem verdadeiramente humano sabe ir procurar, sem ostentação." "Amai-vos uns aos outros, eis toda a lei, lei divina, mediante a qual governa Deus os mundos. O amor é a lei de atração para os seres vivos e organizados. A atração é a lei de amor para a matéria inorgânica." "Não esqueçais nunca que o Espírito, qualquer que sejam o grau de seu adiantamento, sua situação como reencarnado, ou na erraticidade, está sempre colocado entre um superior, que o guia e aperfeiçoa, e um inferior, para com o qual tem que cumprir esses mesmos deveres. Sede, pois, caridosos, praticando, não só a caridade que vos faz dar friamente o óbolo que tirais do bolso ao que vo-lo ousa pedir, mas a que vos leve ao encontro das misérias ocultas. Sede indulgentes com os defeitos dos vossos semelhantes. Em vez de votardes desprezo à ignorância e ao vício, instruí os ignorantes e moralizai os viciados. Sede brandos e benevolentes para com tudo o que vos seja inferior. Sede-o para com os seres mais ínfimos da criação e tereis obedecido à lei de Deus.', 'rascunho'),
  (889, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Não há homens que se vêem condenados a mendigar por culpa sua?', 'Sem dúvida; mas, se uma boa educação moral lhes houvera ensinado a praticar a lei de Deus, não teriam caído nos excessos causadores da sua perdição. Disso, sobretudo, é que depende a melhoria do vosso planeta.', 'rascunho'),
  (890, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Será uma virtude o amor materno, ou um sentimento instintivo, comum aos homens e aos animais?', 'Uma e outra coisa. A Natureza deu à mãe o amor a seus filhos no interesse da conservação deles. No animal, porém, esse amor se limita às necessidades materiais; cessa quando desnecessários se tornam os cuidados. No homem, persiste pela vida inteira e comporta um devotamento e uma abnegação que são virtudes. Sobrevive mesmo à morte e acompanha o filho até no além-túmulo. Bem vedes que há nele coisa diversa do que há no amor do animal." (205-385)', 'rascunho'),
  (891, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Estando em a Natureza o amor materno, como é que há mães que odeiam os filhos e, não raro, desde a infância destes?', 'Às vezes, é uma prova que o Espírito do filho escolheu, ou uma expiação, se aconteceu ter sido mau pai, ou mãe perversa, ou mau filho, noutra existência. Em todos os casos, a mãe má não pode deixar de ser animada por um mau Espírito que procura criar embaraços ao filho, a fim de que sucumba na prova que 282 – Allan Kar dec buscou. Mas, essa violação das leis da Natureza não ficará impune e o Espírito do filho será recompensado pelos obstáculos de que haja triunfado.', 'rascunho'),
  (892, 'Parte Terceira — Das leis morais', 'Capítulo XI — Da lei de justiça, de amor e de caridade', 'Quando os filhos causam desgostos aos pais, não têm estes desculpa para o fato de lhes não dispensarem a ternura de que os fariam objeto, em caso contrário?', 'Não, porque isso representa um encargo que lhes é confiado e a missão deles consiste em se esforçarem por encaminhar os filhos para o bem (582-583). Demais, esses desgostos são, amiúde, a conseqüência do mau feitio que os pais deixaram que seus filhos tomassem desde o berço. Colhem o que semearam.', 'rascunho'),
  (893, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Qual a mais meritória de todas as virtudes?', 'Toda virtude tem seu mérito próprio, porque todas indicam progresso na senda do bem. Há virtude sempre que há resistência voluntária ao arrastamento dos maus pendores. A sublimidade da virtude, porém, está no sacrifício do interesse pessoal, pelo bem do próximo, sem pensamento oculto. A mais meritória é a que assenta na mais desinteressada caridade.', 'rascunho'),
  (894, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Há pessoas que fazem o bem espontaneamente, sem que precisem vencer quaisquer sentimentos que lhes sejam opostos. Terão tanto mérito, quanto as que se vêem na contingência de lutar contra a natureza que lhes é própria e a vencem?', 'Só não têm que lutar aqueles em quem já há progresso realizado. Esses lutaram outrora e triunfaram. Por isso é que os bons sentimentos nenhum esforço lhes custam e suas ações lhes parecem simplíssimas. O bem se lhes tornou um hábito. Devidas lhes são as honras que se costuma tributar a velhos guerreiros que conquistaram seus altos postos." "Como ainda estais longe da perfeição, tais exemplos vos espantam pelo contraste com o que tendes à vista e tanto mais os admirais, quanto mais raros são. Ficai sabendo, porém, que, nos mundos mais adiantados do que o vosso, constitui a regra o que entre vós representa a exceção. Em todos os pontos desses mundos, o sentimento do bem é espontâneo, porque somente bons Espíritos os habitam. Lá, uma só intenção maligna seria monstruosa exceção. Eis por que neles os homens são ditosos. O mesmo se dará na Terra, quando a Humanidade se houver transformado, quando compreender e praticar a caridade na sua verdadeira acepção." 284 – Allan Kar dec', 'rascunho'),
  (895, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Postos de lado os defeitos e os vícios acerca dos quais ninguém se pode equivocar, qual o sinal mais característico da imperfeição?', 'O interesse pessoal. Freqüentemente, as qualidades morais são como, num objeto de cobre, a douradura que não resiste à pedra de toque. Pode um homem possuir qualidades reais, que levem o mundo a considerá-lo homem de bem. Mas, essas qualidades, conquanto assinalem um progresso, nem sempre suportam certas provas e às vezes basta que se fira a corda do interesse pessoal para que o fundo fique a descoberto. O verdadeiro desinteresse é coisa ainda tão rara na Terra que, quando se patenteia, todos o admiram como se fora um fenômeno." "O apego às coisas materiais constitui sinal notório de inferioridade, porque, quanto mais se aferrar aos bens deste mundo, tanto menos compreende o homem o seu destino. Pelo desinteresse, ao contrário, demonstra que encara de um ponto mais elevado o futuro.', 'rascunho'),
  (896, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Há pessoas desinteressadas, mas sem discernimento, que prodigalizam seus haveres sem utilidade real, por lhes não saberem dar emprego criterioso. Têm algum merecimento essas pessoas?', 'Têm o do desinteresse, porém não o do bem que poderiam fazer. O desinteresse é uma virtude, mas a prodigalidade irrefletida constitui sempre, pelo menos, falta de juízo. A riqueza, assim como não é dada a uns para ser aferrolhada num cofre forte, também não o é a outros para ser dispersada ao vento. Representa um depósito de que uns e outros terão de prestar contas, porque terão de responder por todo o bem que podiam fazer e não fizeram, por todas as lágrimas que podiam ter estancado com o dinheiro que deram aos que dele não precisavam.', 'rascunho'),
  (897, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Merecerá reprovação aquele que faz o bem, sem visar a qualquer recompensa na Terra, mas esperando que lhe seja levado em conta na outra vida e que lá venha a ser melhor a sua situação? E essa preocupação lhe prejudicará o progresso?', 'O bem deve ser feito caritativamente, isto é, com desinteresse." a) — Contudo, todos alimentam o desejo muito natural de progredir, para forrar-se à penosa condição desta vida. Os próprios Espíritos nos ensinam a praticar o bem com esse objetivo. Será, então, um mal pensarmos que, praticando o bem, podemos esperar coisa melhor do que temos na Terra? "Não, certamente; mas aquele que faz o bem, sem idéia preconcebida, pelo só prazer de ser agradável a Deus e ao seu próximo que sofre, já se acha num certo grau de progresso, que lhe permitirá alcançar a felicidade muito mais depressa do que seu irmão que, mais positivo, faz o bem por cálculo e não impelido pelo ardor natural do seu coração." b) — Não haverá aqui uma distinção a estabelecer-se entre o bem que podemos fazer ao nosso próximo e o cuidado que pomos em corrigir-nos dos nossos defeitos? Concebemos que seja pouco meritório fazermos o bem com a idéia de que nos seja levado em conta na outra vida; mas será igualmente indício de inferioridade emendarmo-nos, vencermos as nossas paixões, corrigirmos o nosso caráter, com o propósito de nos aproximarmos dos bons Espíritos e de nos elevarmos? "Não, não. Quando dizemos — fazer o bem, queremos significar — ser caridoso. Procede como egoísta todo aquele que calcula o que lhe possa cada uma de suas boas ações render na vida futura, tanto quanto na vida terrena. Nenhum egoísmo, porém, há em querer o homem melhorar-se, para se aproximar de Deus, pois que é o fim para o qual devem todos tender.', 'rascunho'),
  (898, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Sendo a vida corpórea apenas uma estada temporária neste mundo e devendo o futuro constituir objeto da nossa principal preocupação, será útil nos esforcemos por adquirir conhecimentos científicos que só digam respeito às coisas e às necessidades materiais?', 'Sem dúvida. Primeiramente, isso vos põe em condições de auxiliar os vossos irmãos; depois, o vosso Espírito subirá mais depressa, se já houver progredido em inteligência. Nos intervalos das encarnações, aprendereis numa hora o que na Terra vos exigiria anos de aprendizado. Nenhum conhecimento é inútil; todos mais ou menos contribuem para o progresso, porque o Espírito, para ser perfeito, tem que saber tudo, e porque, cumprindo que o progresso se efetue em todos os sentidos, todas as idéias adquiridas ajudam o desenvolvimento do Espírito.', 'rascunho'),
  (899, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Qual o mais culpado de dois homens ricos que empregam exclusivamente em gozos pessoais suas riquezas, tendo um nascido na opulência e desconhecido sempre a necessidade, devendo o outro ao seu trabalho os bens que possui?', 'Aquele que conheceu os sofrimentos, porque sabe o que é sofrer. A dor, a que nenhum alívio procura dar, ele a conhece; porém, como freqüentemente sucede, já dela se não lembra.', 'rascunho'),
  (900, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Aquele que incessantemente acumula haveres, sem fazer o bem a quem quer que seja, achará desculpa, que valha, na circunstância de acumular com o fito de maior soma legar aos seus herdeiros?', 'É um compromisso com a consciência má.', 'rascunho'),
  (901, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Figuremos dois avarentos, um dos quais nega a si mesmo o necessário e morre de miséria sobre o seu tesouro, ao passo que o segundo só o é para os outros, mostrando-se pródigo para consigo mesmo; enquanto recua ante o mais ligeiro sacrifício para prestar um serviço ou fazer qualquer coisa útil, nunca julga demasiado o que despenda para satisfazer aos seus gostos ou às suas paixões. Peça- se-lhe um obséquio e estará sempre em dificuldade para fazê-lo; imagine, porém, realizar uma fantasia e terá sempre o bastante para isso. Qual o mais culpado e qual o que se achará em pior situação no mundo dos Espíritos?', 'O que goza, porque é mais egoísta do que avarento. O outro já recebeu parte do seu castigo.', 'rascunho'),
  (902, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Será reprovável que cobicemos a riqueza, quando nos anime o desejo de fazer o bem?', 'Tal sentimento é, não há dúvida, louvável, quando puro. Mas, será sempre bastante desinteressado esse desejo? Não ocultará nenhum intuito de ordem pessoal? Não será de fazer o bem a si mesmo, em primeiro lugar, que cogita aquele, em quem tal desejo se manifesta?" 286 – Allan Kar dec', 'rascunho'),
  (903, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Incorre em culpa o homem, por estudar os defeitos alheios?', 'Incorrerá em grande culpa, se o fizer para os criticar e divulgar, porque será faltar com a caridade. Se o fizer, para tirar daí proveito, para evitá-los, tal estudo poderá ser-lhe de alguma utilidade. Importa, porém, não esquecer que a indulgência para com os defeitos de outrem é uma das virtudes contidas na caridade. Antes de censurardes as imperfeições dos outros, vede se de vós não poderão dizer o mesmo. Tratai, pois, de possuir as qualidades opostas aos defeitos que criticais no vosso semelhante. Esse o meio de vos tornardes superiores a ele. Se lhe censurais o ser avaro, sede generosos; se o ser orgulhoso, sede humildes e modestos; se o ser áspero, sede brandos; se o proceder com pequenez, sede grandes em todas as vossas ações. Numa palavra, fazei por maneira que se não vos possam aplicar estas palavras de Jesus: Vê o argueiro no olho do seu vizinho e não vê a trave no seu próprio.', 'rascunho'),
  (904, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Incorrerá em culpa aquele que sonda as chagas da sociedade e as expõe em público?', 'Depende do sentimento que o mova. Se o escritor apenas visa produzir escândalo, não faz mais do que proporcionar a si mesmo um gozo pessoal, apresentando quadros que constituem antes mau do que bom exemplo. O Espírito aprecia isso, mas pode vir a ser punido por essa espécie de prazer que encontra em revelar o mal." a) — Como, em tal caso, julgar da pureza das intenções e da sinceridade do escritor? "Nem sempre há nisso utilidade. Se ele escrever boas coisas, aproveitai-as. Se proceder mal, é uma questão de consciência que lhe diz respeito, exclusivamente. Demais, se o escritor tem empenho em provar a sua sinceridade, apóie o que disser nos exemplos que dê.', 'rascunho'),
  (905, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Alguns autores hão publicado belíssimas obras de grande moral, que auxiliam o progresso da Humanidade, das quais, porém, nenhum proveito tiraram eles. Ser- lhes-á levado em conta, como Espíritos, o bem a que suas obras hajam dado lugar?', 'A moral sem as ações é o mesmo que a semente sem o trabalho. De que vos serve a semente, se não a fazeis dar frutos que vos alimentem? Grave é a culpa desses homens, porque dispunham de inteligência para compreender. Não praticando as máximas que ofereciam aos outros, renunciaram a colher-lhes os frutos.', 'rascunho'),
  (906, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Será passível de censura o homem, por ter consciência do bem que faz e por confessá-lo a si mesmo?', 'Pois que pode ter consciência do mal que pratica, do bem igualmente deve tê-la, a fim de saber se andou bem ou mal. Pesando todos os seus atos na balança da lei de Deus e, sobretudo, na da lei de justiça, amor e caridade, é que poderá dizer a si mesmo se suas obras são boas ou más, que as poderá aprovar ou desaprovar. Não se lhe pode, portanto, censurar que reconheça haver triunfado dos maus pendores e que se sinta satisfeito, desde que de tal não se envaideça, porque então cairia noutra falta.', 'rascunho'),
  (907, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Será substancialmente mau o princípio originário das paixões, embora esteja na natureza?', 'Não; a paixão está no excesso de que se acresceu a vontade, visto que o princípio que lhe dá origem foi posto no homem para o bem, tanto que as paixões podem levá-lo à realização de grandes coisas. O abuso que delas se faz é que causa o mal.', 'rascunho'),
  (908, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Como se poderá determinar o limite onde as paixões deixam de ser boas para se tornarem más?', 'As paixões são como um corcel, que só tem utilidade quando governado e que se torna perigoso desde que passe a governar. Uma paixão se torna perigosa a partir do momento em que deixais de poder governá-la e que dá em resultado um prejuízo qualquer para vós mesmos, ou para outrem." As paixões são alavancas que decuplicam as forças do homem e o auxiliam na execução dos desígnios da Providência. Mas, se, em vez de as dirigir, deixa que elas o dirijam, cai o homem nos excessos e a própria força que, manejada pelas suas mãos, poderia produzir o bem, contra ele se volta e o esmaga. Todas as paixões têm seu princípio num sentimento, ou numa necessidade natural. O princípio das paixões não é, assim, um mal, pois que assenta numa das condições providenciais da nossa existência. A paixão propriamente dita é a exageração de uma necessidade ou de um sentimento. Está no excesso e não na causa e este excesso se torna um mal, quando tem como conseqüência um mal qualquer. Toda paixão que aproxima o homem da natureza animal afasta-o da natureza espiritual. Todo sentimento que eleva o homem acima da natureza animal denota predominância do Espírito sobre a matéria e o aproxima da perfeição.', 'rascunho'),
  (909, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Poderia sempre o homem, pelos seus esforços, vencer as suas más inclinações?', 'Sim, e, freqüentemente, fazendo esforços muito insignificantes. O que lhe falta é a vontade. Ah! quão poucos dentre vós fazem esforços!', 'rascunho'),
  (910, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Pode o homem achar nos Espíritos eficaz assistência para triunfar de suas paixões?', 'Se o pedir a Deus e ao seu bom gênio, com sinceridade, os bons Espíritos lhe virão certamente em auxílio, porquanto é essa a missão deles.', 'rascunho'),
  (911, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Não haverá paixões tão vivas e irresistíveis, que a vontade seja impotente para dominá-las?', 'Há muitas pessoas que dizem: Quero, mas a vontade só lhes está nos lábios. Querem, porém muito satisfeitas ficam que não seja como ‘querem’. Quando o homem crê que não pode vencer as suas paixões, é que seu Espírito se compraz nelas, em conseqüência da sua inferioridade. Compreende a sua natureza espiritual aquele que as procura reprimir. Vencê-las é, para ele, uma vitória do Espírito sobre a matéria." 288 – Allan Kar dec', 'rascunho'),
  (912, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Qual o meio mais eficiente de combater-se o predomínio da natureza corpórea?', 'Praticar a abnegação.', 'rascunho'),
  (913, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Dentre os vícios, qual o que se pode considerar radical?', 'Temo-lo dito muitas vezes: o egoísmo. Daí deriva todo mal. Estudai todos os vícios e vereis que no fundo de todos há egoísmo. Por mais que lhes deis combate, não chegareis a extirpá-los, enquanto não atacardes o mal pela raiz, enquanto não lhe houverdes destruído a causa. Tendam, pois, todos os esforços para esse efeito, porquanto aí é que está a verdadeira chaga da sociedade. Quem quiser, desde esta vida, ir aproximando-se da perfeição moral, deve expurgar o seu coração de todo sentimento de egoísmo, visto ser o egoísmo incompatível com a justiça, o amor e a caridade. Ele neutraliza todas as outras qualidades.', 'rascunho'),
  (914, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Fundando-se o egoísmo no sentimento do interesse pessoal, bem difícil parece extirpá-lo inteiramente do coração humano. Chegar-se-á a consegui-lo?', 'À medida que os homens se instruem acerca das coisas espirituais, menos valor dão às coisas materiais. Depois, necessário é que se reformem as instituições humanas que o entretêm e excitam. Isso depende da educação.', 'rascunho'),
  (915, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Por ser inerente à espécie humana, o egoísmo não constituirá sempre um obstáculo ao reinado do bem absoluto na Terra?', 'É exato que no egoísmo tendes o vosso maior mal, porém ele se prende à inferioridade dos Espíritos encarnados na Terra e não à Humanidade mesma. Ora, depurando-se por encarnações sucessivas, os Espíritos se despojam do egoísmo, como de suas outras impurezas. Não existirá na Terra nenhum homem isento de egoísmo e praticante da caridade? Há muito mais homens assim do que supondes. Apenas, não os conheceis, porque a virtude foge à viva claridade do dia. Desde que haja um, por que não haverá dez? havendo dez, por que não haverá mil e assim por diante?', 'rascunho'),
  (916, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Longe de diminuir, o egoísmo cresce com a civilização, que, até, parece, o excita e mantém. Como poderá a causa destruir o efeito?', 'Quanto maior é o mal, mais hediondo se torna. Era preciso que o egoísmo produzisse muito mal, para que compreensível se fizesse a necessidade de extirpá-lo. Os homens, quando se houverem despojado do egoísmo que os domina, viverão como irmãos, sem se fazerem mal algum, auxiliando-se reciprocamente, impelidos pelo sentimento mútuo da solidariedade. Então, o forte será o amparo e não o opressor do fraco e não mais serão vistos homens a quem falte o indispensável, porque todos praticarão a lei de justiça. Esse o reinado do bem, que os Espíritos estão incumbidos de preparar.', 'rascunho'),
  (917, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Qual o meio de destruir-se o egoísmo?', 'De todas as imperfeições humanas, o egoísmo é a mais difícil de desenraizar-se porque deriva da influência da matéria, influência de que o homem, ainda muito próximo de sua origem, não pôde libertar-se e para cujo entretenimento tudo concorre: suas leis, sua organização social, sua educação. O egoísmo se enfraquecerá à proporção que a vida moral for predominando sobre a vida material e, sobretudo, com a compreensão, que o Espiritismo vos faculta, do vosso estado futuro, real e não desfigurado por ficções alegóricas. Quando, bem compreendido, se houver identificado com os costumes e as crenças, o Espiritismo transformará os hábitos, os usos, as relações sociais. O egoísmo assenta na importância da personalidade. Ora, o Espiritismo, bem compreendido, repito, mostra as coisas de tão alto que o sentimento da personalidade desaparece, de certo modo, diante da imensidade. Destruindo essa importância, ou, pelo menos, reduzindo-a às suas legítimas proporções, ele necessariamente combate o egoísmo.’ "O choque, que o homem experimenta, do egoísmo dos outros é o que muitas vezes o faz egoísta, por sentir a necessidade de colocar-se na defensiva. Notando que os outros pensam em si próprios e não nele, ei-lo levado a ocupar-se consigo, mais do que com os outros. Sirva de base às instituições sociais, às relações legais de povo a povo e de homem a homem o princípio da caridade e da fraternidade e cada um pensará menos na sua pessoa, assim veja que outros nela pensaram. Todos experimentarão a influência moralizadora do exemplo e do contacto. Em face do atual extravasamento de egoísmo, grande virtude é verdadeiramente necessária, para que alguém renuncie à sua personalidade em proveito dos outros, que, de ordinário, absolutamente lhe não agradecem. Principalmente para os que possuem essa virtude, é que o reino dos céus se acha aberto. A esses, sobretudo, é que está reservada a felicidade dos eleitos, pois em verdade vos digo que, no dia da justiça, será posto de lado e sofrerá pelo abandono, em que se há de ver, todo aquele que em si somente houver pensado.', 'rascunho'),
  (918, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Por que indícios se pode reconhecer em um homem o progresso real que lhe elevará o Espírito na hierarquia espírita?', 'O Espírito prova a sua elevação, quando todos os atos de sua vida corporal representam a prática da lei de Deus e quando antecipadamente compreende a vida espiritual." Verdadeiramente, homem de bem é o que pratica a lei de justiça, amor e caridade, na sua maior pureza. Se interrogar a própria consciência sobre os atos que praticou, perguntará se não transgrediu essa lei, se não fez o mal, se fez todo bem que podia, se ninguém tem motivos para dele se queixar, enfim se fez aos outros o que desejara que lhe fizessem. Possuído do sentimento de caridade e de amor ao próximo, faz o bem pelo bem, sem contar com qualquer retribuição, e sacrifica seus interesses à justiça. É bondoso, humanitário e benevolente para com todos, porque vê irmãos em todos os homens, sem distinção de raças, nem de crenças. Se Deus lhe outorgou o poder e a riqueza, considera essas coisas como UM DEPÓSITO, de que lhe cumpre usar para o bem. Delas não se envaidece, por saber que Deus, que lhas deu, também lhas pode retirar. Se sob a sua dependência a ordem social colocou outros homens, trata-os com bondade e complacência, porque são seus iguais perante Deus. Usa da sua autoridade para lhes levantar o moral e não para os esmagar com o seu orgulho. É indulgente para com as fraquezas alheias, porque sabe que também precisa da indulgência dos outros e se lembra destas palavras do Cristo: Atire a primeira pedra aquele que estiver sem pecado. Não é vingativo. A exemplo de Jesus, perdoa as ofensas, para só se lembrar dos benefícios, pois não ignora que, como houver perdoado, assim perdoado lhe será. Respeita, enfim, em seus semelhantes, todos os direitos que as leis da Natureza lhes concedem, como quer que os mesmos direitos lhe sejam respeitados.', 'rascunho'),
  (919, 'Parte Terceira — Das leis morais', 'Capítulo XII — Da perfeição moral', 'Qual o meio prático mais eficaz que tem o homem de se melhorar nesta vida e de resistir à atração do mal?', 'Um sábio da antiguidade vo-lo disse: Conhece-te a ti mesmo." a) — Conhecemos toda a sabedoria desta máxima, porém a dificuldade está precisamente em cada um conhecer-se a si mesmo. Qual o meio de consegui- lo? "Fazei o que eu fazia, quando vivi na Terra: ao fim do dia, interrogava a minha consciência, passava revista ao que fizera e perguntava a mim mesmo se não faltara a algum dever, se ninguém tivera motivo para de mim se queixar. Foi assim que cheguei a me conhecer e a ver o que em mim precisava de reforma. Aquele que, todas as noites, evocasse todas as ações que praticara durante o dia e inquirisse de si mesmo o bem ou o mal que houvera feito, rogando a Deus e ao seu anjo-de-guarda que o esclarecessem, grande força adquiriria para se aperfeiçoar, porque, crede-me, Deus o assistiria. Dirigi, pois, a vós mesmos perguntas, interrogai-vos sobre o que tendes feito e com que objetivo procedestes em tal ou tal circunstância, sobre se fizestes alguma coisa que, feita por outrem, censuraríeis, sobre se obrastes alguma ação que não ousaríeis confessar. Perguntai ainda mais: ‘Se aprouvesse a Deus chamar-me neste momento, teria que temer o olhar de alguém, ao entrar de novo no mundo dos Espíritos, onde nada pode ser ocultado?’ "Examinai o que pudestes ter obrado contra Deus, depois contra o vosso próximo e, finalmente, contra vós mesmos. As respostas vos darão, ou o descanso para a vossa consciência, ou a indicação de um mal que precise ser curado." "O conhecimento de si mesmo é, portanto, a chave do progresso individual. Mas, direis, como há de alguém julgar-se a si mesmo? Não está aí a ilusão do amor- próprio para atenuar as faltas e torná-las desculpáveis? O avarento se considera apenas econômico e previdente; o orgulhoso julga que em si só há dignidade. Isto é muito real, mas tendes um meio de verificação que não pode iludir-vos. Quando estiverdes indecisos sobre o valor de uma de vossas ações, inquiri como a qualificaríeis, se praticada por outra pessoa. Se a censurais noutrem, não na podereis ter por legítima quando fordes o seu autor, pois que Deus não usa de duas medidas na aplicação de sua justiça. Procurai também saber o que dela pensam os vossos semelhantes e não desprezeis a opinião dos vossos inimigos, porquanto esses nenhum interesse têm em mascarar a verdade e Deus muitas vezes os coloca ao vosso lado como um espelho, a fim de que sejais advertidos com mais franqueza do que o faria um amigo. Perscrute, conseguintemente, a sua consciência aquele que se sinta possuído do desejo sério de melhorar-se, a fim de extirpar de si os maus pendores, como do seu jardim arranca as ervas daninhas; dê balanço no seu dia moral para, a exemplo do comerciante, avaliar suas perdas e seus lucros e eu vos asseguro que a conta destes será mais avultada que a daquelas. Se puder dizer que 292 – Allan Kar dec foi bom o seu dia, poderá dormir em paz e aguardar sem receio o despertar na outra vida." "Formulai, pois, de vós para convosco, questões nítidas e precisas e não temais multiplicá-las. Justo é que se gastem alguns minutos para conquistar uma felicidade eterna. Não trabalhais todos os dias com o fito de juntar haveres que vos garantam repouso na velhice? Não constitui esse repouso o objeto de todos os vossos desejos, o fim que vos faz suportar fadigas e privações temporárias? Pois bem! que é esse descanso de alguns dias, turbado sempre pelas enfermidades do corpo, em comparação com o que espera o homem de bem? Não valerá este outro a pena de alguns esforços? Sei haver muitos que dizem ser positivo o presente e incerto o futuro. Ora, esta exatamente a idéia que estamos encarregados de eliminar do vosso íntimo, visto desejarmos fazer que compreendais esse futuro, de modo a não restar nenhuma dúvida em vossa alma. Por isso foi que primeiro chamamos a vossa atenção por meio de fenômenos capazes de ferir-vos os sentidos e que agora vos damos instruções, que cada um de vós se acha encarregado de espalhar. Com este objetivo é que ditamos O Livro dos Espíritos.', 'rascunho'),
  (920, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Pode o homem gozar de completa felicidade na Terra?', 'Não, por isso que a vida lhe foi dada como prova ou expiação. Dele, porém, depende a suavização de seus males e o ser tão feliz quanto possível na Terra.', 'rascunho'),
  (921, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Concebe-se que o homem será feliz na Terra, quando a Humanidade estiver transformada. Mas, enquanto isso se não verifica, poderá conseguir uma felicidade relativa?', 'O homem é quase sempre o obreiro da sua própria infelicidade. Praticando a lei de Deus, a muitos males se forrará e proporcionará a si mesmo felicidade tão grande quanto o comporte a sua existência grosseira." Aquele que se acha bem compenetrado de seu destino futuro não vê na vida corporal mais do que uma estação temporária, uma como parada momentânea em péssima hospedaria. Facilmente se consola de alguns aborrecimentos passageiros de uma viagem que o levará a tanto melhor posição, quanto melhor tenha cuidado dos preparativos para empreendê-la. Já nesta vida somos punidos pelas infrações, que cometemos, das leis que regem a existência corpórea, sofrendo os males conseqüentes dessas mesmas infrações e dos nossos próprios excessos. Se, gradativamente, remontarmos à origem do que chamamos as nossas desgraças terrenas, veremos que, na maioria dos casos, elas são a conseqüência de um primeiro afastamento nosso do caminho reto. Desviando-nos deste, enveredamos por outro, mau, e, de conseqüência em conseqüência, caímos na desgraça.', 'rascunho'),
  (922, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'A felicidade terrestre é relativa à posição de cada um. O que basta para a felicidade de um, constitui a desgraça de outro. Haverá, contudo, alguma soma de felicidade comum a todos os homens?', 'Com relação à vida material, é a posse do necessário. Com relação à vida moral, a consciência tranqüila e a fé no futuro.', 'rascunho'),
  (923, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'O que para um é supérfluo não representará, para outro, o necessário, e reciprocamente, de acordo com as posições respectivas?', 'Sim, conformemente às vossas idéias materiais, aos vossos preconceitos, à vossa ambição e às vossas ridículas extravagâncias, a que o futuro fará justiça, quando compreenderdes a verdade. Não há dúvida de que aquele que tinha cinqüenta mil libras de renda, vendo-se reduzido a só ter dez mil, se considera muito desgraçado, por não mais poder fazer a mesma figura, conservar o que chama a sua posição, ter cavalos, lacaios, satisfazer a todas as paixões, etc. Acredita que lhe falta o necessário. Mas, francamente, achas que seja digno de lástima, quando ao seu lado muitos há, morrendo de fome e frio, sem um abrigo onde repousem a cabeça? O homem criterioso, a fim de ser feliz, olha sempre para baixo e não para cima, a não ser para elevar sua alma ao infinito.', 'rascunho'),
  (924, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Há males que independem da maneira de proceder do homem e que atingem mesmo os mais justos. Nenhum meio terá ele de os evitar?', 'Deve resignar-se e sofrê-los sem murmurar, se quer progredir. Sempre, porém, lhe é dado haurir consolação na própria consciência, que lhe proporciona a esperança de melhor futuro, se fizer o que é preciso para obtê-lo.', 'rascunho'),
  (925, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Por que favorece Deus, com os dons da riqueza, a certos homens que não parecem tê-los merecido?', 'Isso significa um favor aos olhos dos que apenas vêem o presente. Mas, fica sabendo, a riqueza é, de ordinário, prova mais perigosa do que a miséria." (814 e seguintes)', 'rascunho'),
  (926, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Criando novas necessidades, a civilização não constitui uma fonte de novas aflições?', 'Os males deste mundo estão na razão das necessidades factícias que vos criais. A muitos desenganos se poupa nesta vida aquele que sabe restringir seus desejos e olha sem inveja para o que esteja acima de si. O que menos necessidades tem, esse o mais rico." "Invejais os gozos dos que vos parecem os felizes do mundo. Sabeis, porventura, o que lhes está reservado? Se os seus gozos são todos pessoais, pertencem eles ao número dos egoístas: o reverso então virá. Deveis, de preferência, lastimá-los. Deus algumas vezes permite que o mau prospere, mas a sua felicidade não é de causar inveja, porque com lágrimas amargas a pagará. Quando um justo é infeliz, isso representa uma prova que lhe será levada em conta, se a suportar com coragem. Lembrai-vos destas palavras de Jesus: Bem-aventurados os que sofrem, pois que serão consolados.', 'rascunho'),
  (927, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Não há dúvida que, à felicidade, o supérfluo não é forçosamente indispensável, porém o mesmo não se dá com o necessário. Ora, não será real a infelicidade daqueles a quem falta o necessário? 296 – Allan Kar dec', 'Verdadeiramente infeliz o homem só o é quando sofre da falta do necessário à vida e à saúde do corpo. Todavia, pode acontecer que essa privação seja de sua culpa. Então, só tem que se queixar de si mesmo. Se for ocasionada por outrem, a responsabilidade recairá sobre aquele que lhe houver dado causa.', 'rascunho'),
  (928, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Evidentemente, por meio da especialidade das aptidões naturais, Deus indica a nossa vocação neste mundo. Muitos dos nossos males não advirão de não seguirmos essa vocação?', 'Assim é, de fato, e muitas vezes são os pais que, por orgulho ou avareza, desviam seus filhos da senda que a Natureza lhes traçou, comprometendo-lhes a felicidade, por efeito desse desvio. Responderão por ele." a) — Acharíeis então justo que o filho de um homem altamente colocado na sociedade fabricasse tamancos, por exemplo, desde que para isso tivesse aptidão? "Cumpre não cair no absurdo, nem exagerar coisa alguma: a civilização tem suas exigências. Por que haveria de fabricar tamancos o filho de um homem altamente colocado, como dizes, se pode fazer outra coisa? Poderá sempre tornar-se útil na medida de suas faculdades, desde que não as aplique às avessas. Assim, por exemplo, em vez de mau advogado, talvez desse bom mecânico, etc." No afastarem-se os homens da sua esfera intelectual reside indubitavelmente uma das mais freqüentes causas de decepção. A inaptidão para a carreira abraçada constitui fonte inesgotável de reveses. Depois, o amor-próprio, sobrevindo a tudo isso, impede que o que fracassou recorra a uma profissão mais humilde e lhe mostra o suicídio como remédio para escapar ao que se lhe afigura humilhação. Se uma educação moral o houvesse colocado acima dos tolos preconceitos do orgulho, jamais se teria deixado apanhar desprevenido.', 'rascunho'),
  (929, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Pessoas há, que, baldas de todos os recursos, embora no seu derredor reine a abundância, só têm diante de si a perspectiva da morte. Que partido devem tomar? Devem deixar-se morrer de fome?', 'Nunca ninguém deve ter a idéia de deixar-se morrer de fome. O homem acharia sempre meio de se alimentar, se o orgulho não se colocasse entre a necessidade e o trabalho. Costuma-se dizer: ‘Não há ofício desprezível; o seu estado não é o que desonra o homem.’ Isso, porém, cada um diz para os outros e não para si.', 'rascunho'),
  (930, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'É evidente que, se não fossem os preconceitos sociais, pelos quais se deixa o homem dominar, ele sempre acharia um trabalho qualquer, que lhe proporcionasse meio de viver, embora deslocando-se da sua posição. Mas, entre os que não têm preconceitos ou os põem de lado, não há pessoas que se vêem na impossibilidade de prover às suas necessidades, em conseqüência de moléstias ou outras causas independentes da vontade delas?', 'Numa sociedade organizada segundo a lei do Cristo ninguém deve morrer de fome." Com uma organização social criteriosa e previdente, ao homem só por culpa sua pode faltar o necessário. Porém, suas próprias faltas são freqüentemente resultado do meio onde se acha colocado. Quando praticar a lei de Deus, terá uma ordem social fundada na justiça e na solidariedade e ele próprio também será melhor.', 'rascunho'),
  (931, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Por que são mais numerosas, na sociedade, as classes sofredoras do que as felizes?', 'Nenhuma é perfeitamente feliz e o que julgais ser a felicidade muitas vezes oculta pungentes aflições. O sofrimento está por toda parte. Entretanto, para responder ao teu pensamento, direi que as classes a que chamas sofredoras são mais numerosas, por ser a Terra lugar de expiação. Quando a houver transformado em morada do bem e de Espíritos bons, o homem deixará de ser infeliz aí e ela lhe será o paraíso terrestre.', 'rascunho'),
  (932, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Por que, no mundo, tão amiúde, a influência dos maus sobrepuja a dos bons?', 'Por fraqueza destes. Os maus são intrigantes e audaciosos, os bons são tímidos. Quando estes o quiserem, preponderarão.', 'rascunho'),
  (933, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Assim como, quase sempre, é o homem o causador de seus sofrimentos materiais, também o será de seus sofrimentos morais?', 'Mais ainda, porque os sofrimentos materiais algumas vezes independem da vontade; mas, o orgulho ferido, a ambição frustrada, a ansiedade da avareza, a inveja, o ciúme, todas as paixões, numa palavra, são torturas da alma." "A inveja e o ciúme! Felizes os que desconhecem estes dois vermes roedores! Para aquele que a inveja e o ciúme atacam, não há calma, nem repouso possíveis. À sua frente, como fantasmas que lhe não dão tréguas e o perseguem até durante o sono, se levantam os objetos de sua cobiça, do seu ódio, do seu despeito. O invejoso e o ciumento vivem ardendo em contínua febre. Será essa uma situação desejável e não compreendeis que, com as suas paixões, o homem cria para si mesmo suplícios voluntários, tornando-se-lhe a Terra verdadeiro inferno?" Muitas expressões pintam energicamente o efeito de certas paixões. Diz-se: ímpar de orgulho, morrer de inveja, secar de ciúme ou de despeito, não comer nem beber de ciúmes, etc. Este quadro é sumamente real. Acontece até não ter o ciúme objeto determinado. Há pessoas ciumentas, por natureza, de tudo o que se eleva, de tudo o que sai da craveira vulgar, embora nenhum interesse direto tenham, mas unicamente porque não podem conseguir outro tanto. Ofusca-as tudo o que lhes parece estar acima do horizonte e, se constituíssem maioria na sociedade, trabalhariam para reduzir tudo ao nível em que se acham. É o ciúme aliado à mediocridade. De ordinário, o homem só é infeliz pela importância que liga às coisas deste mundo. Fazem-lhe a infelicidade a vaidade, a ambição e a cobiça desiludidas. Se se colocar fora do círculo acanhado da vida material, se elevar seus pensamentos para o infinito, que é seu destino, mesquinhas e pueris lhe parecerão as vicissitudes da Humanidade, como o são as tristezas da criança que se aflige pela perda de um brinquedo, que resumia a sua felicidade suprema. Aquele que só vê felicidade na satisfação do orgulho e dos apetites grosseiros é infeliz, desde que não os pode satisfazer, ao passo que aquele que nada pede ao supérfluo é feliz com os que outros consideram calamidades. Referimo-nos ao homem civilizado, porquanto, o selvagem, sendo mais limitadas as suas necessidades, não tem os mesmos motivos de cobiça e de angústias. Diversa é a sua maneira de ver as coisas. Como civilizado, o homem raciocina sobre a sua infelicidade e a analisa. Por isso é que esta o fere. Mas, também, lhe é facultado raciocinar sobre os meios de 298 – Allan Kar dec obter consolação e de analisá-los. Essa consolação ele a encontra no sentimento cristão, que lhe dá a esperança de melhor futuro, e no Espiritismo que lhe dá a certeza desse futuro.', 'rascunho'),
  (934, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'A perda dos entes que nos são caros não constitui para nós legítima causa de dor, tanto mais legítima quanto é irreparável e independente da nossa vontade?', 'Essa causa de dor atinge assim o rico, como o pobre: representa uma prova, ou expiação, e comum é a lei. Tendes, porém, uma consolação em poderdes comunicar-vos com os vossos amigos pelos meios que vos estão ao alcance, enquanto não dispondes de outros mais diretos e mais acessíveis aos vossos sentidos.', 'rascunho'),
  (935, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Que se deve pensar da opinião dos que consideram profanação as comunicações com o além-túmulo?', 'Não pode haver nisso profanação, quando haja recolhimento e quando a evocação seja praticada respeitosa e convenientemente. A prova de que assim é tendes no fato de que os Espíritos que vos consagram afeição acodem com prazer ao vosso chamado. Sentem-se felizes por vos lembrardes deles e por se comunicarem convosco. Haveria profanação, se isso fosse feito levianamente." A possibilidade de nos pormos em comunicação com os Espíritos é uma dulcíssima consolação, pois que nos proporciona meio de conversarmos com os nossos parentes e amigos, que deixaram antes de nós a Terra. Pela evocação, aproximamo-los de nós, eles vêm colocar-se ao nosso lado, nos ouvem e respondem. Cessa assim, por bem dizer, toda separação entre eles e nós. Auxiliam-nos com seus conselhos, testemunham-nos o afeto que nos guardam e a alegria que experimentam por nos lembrarmos deles. Para nós, grande satisfação é sabê-los ditosos, informar-nos, por seu intermédio, dos pormenores da nova existência a que passaram e adquirir a certeza de que um dia nos iremos a eles juntar.', 'rascunho'),
  (936, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Como é que as dores inconsoláveis dos que sobrevivem se refletem nos Espíritos que as causam?', 'O Espírito é sensível à lembrança e às saudades dos que lhe eram caros na Terra; mas, uma dor incessante e desarrazoada o toca penosamente, porque, nessa dor excessiva, ele vê falta de fé no futuro e de confiança em Deus e, por conseguinte, um obstáculo ao adiantamento dos que o choram e talvez à sua reunião com estes." Estando o Espírito mais feliz no Espaço que na Terra, lamentar que ele tenha deixado a vida corpórea é deplorar que seja feliz. Figuremos dois amigos que se achem metidos na mesma prisão. Ambos alcançarão um dia a liberdade, mas um a obtém antes do outro. Seria caridoso que o que continuou preso se entristecesse porque o seu amigo foi libertado primeiro? Não haveria, de sua parte, mais egoísmo do que afeição em querer que do seu cativeiro e do seu sofrer partilhasse o outro por igual tempo? O mesmo se dá com dois seres que se amam na Terra. O que parte primeiro é o que primeiro se liberta e só nos cabe felicitá-lo, aguardando com paciência o momento em que a nosso turno também o seremos. Façamos ainda, a este propósito, outra comparação. Tendes um amigo que, junto de vós, se encontra em penosíssima situação. Sua saúde ou seus interesses exigem que vá para outro país, onde estará melhor a todos os respeitos. Deixará temporariamente de se achar ao vosso lado, mas com ele vos correspondereis sempre: a separação será apenas material. Desgostar-vos-ia o seu afastamento, embora para bem dele? Pelas provas patentes, que ministra, da vida futura, da presença, em torno de nós, daqueles a quem amamos, da continuidade da afeição e da solicitude que nos dispensavam; pelas relações que nos faculta manter com eles, a Doutrina Espírita nos oferece suprema consolação, por ocasião de uma das mais legítimas dores. Com o Espiritismo, não mais solidão, não mais abandono: o homem, por muito insulado que esteja, tem sempre perto de si amigos com quem pode comunicar-se. Impacientemente suportamos as tribulações da vida. Tão intoleráveis nos parecem, que não compreendemos possamos sofrê-las. Entretanto, se as tivermos suportado corajosamente, se soubermos impor silêncio às nossas murmurações, felicitar-nos-emos, quando fora desta prisão terrena, como o doente que sofre se felicita, quando curado, por se haver submetido a um tratamento doloroso.', 'rascunho'),
  (937, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Para o homem de coração, as decepções oriundas da ingratidão e da fragilidade dos laços da amizade não são também uma fonte de amarguras?', 'São; porém, deveis lastimar os ingratos e os infiéis; serão muito mais infelizes do que vós. A ingratidão é filha do egoísmo e o egoísta topará mais tarde com corações insensíveis, como o seu próprio o foi. Lembrai-vos de todos os que hão feito mais bem do que vós, que valeram muito mais do que vós e que tiveram por paga a ingratidão. Lembrai-vos de que o próprio Jesus foi, quando no mundo, injuriado e menosprezado, tratado de velhaco e impostor, e não vos admireis de que o mesmo vos suceda. Seja o bem que houverdes feito a vossa recompensa na Terra e não atenteis no que dizem os que hão recebido os vossos benefícios. A ingratidão é uma prova para a vossa perseverança na prática do bem; ser-vos-á levada em conta e os que vos forem ingratos serão tanto mais punidos, quanto maior lhes tenha sido a ingratidão.', 'rascunho'),
  (938, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'As decepções oriundas da ingratidão não serão de molde a endurecer o coração e a fechá-lo à sensibilidade?', 'Fora um erro, porquanto o homem de coração, como dizes, se sente sempre feliz pelo bem que faz. Sabe que, se esse bem for esquecido nesta vida, será lembrado em outra e que o ingrato se envergonhará e terá remorsos da sua ingratidão." a) — Mas, isso não impede que se lhe ulcere o coração. Ora, daí não poderá nascer-lhe a idéia de que seria mais feliz, se fosse menos sensível? "Pode, se preferir a felicidade do egoísta. Triste felicidade essa! Saiba, pois, que os amigos ingratos que o abandonam não são dignos de sua amizade e que se enganou a respeito deles. Assim sendo, não há de que lamentar o tê-los perdido. Mais tarde achará outros, que saberão compreendê-lo melhor. Lastimai os que usam para convosco de um procedimento que não tenhais merecido, pois bem triste se lhes 300 – Allan Kar dec apresentará o reverso da medalha. Não vos aflijais, porém, com isso: será o meio de vos colocardes acima deles." A Natureza deu ao homem a necessidade de amar e de ser amado. Um dos maiores gozos que lhe são concedidos na Terra é o de encontrar corações que com o seu simpatizem. Dá-lhe ela, assim, as primícias da felicidade que o aguarda no mundo dos Espíritos perfeitos, onde tudo é amor e benignidade. Desse gozo está excluído o egoísta.', 'rascunho'),
  (939, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Uma vez que os Espíritos simpáticos são induzidos a unir-se, como é que, entre os encarnados, freqüentemente só de um lado há afeição e que o mais sincero amor se vê acolhido com indiferença e, até, com repulsão? Como é, além disso, que a mais viva afeição de dois seres pode mudar-se em antipatia e mesmo em ódio?', 'Não compreendes então que isso constitui uma punição, se bem que passageira? Depois, quantos não são os que acreditam amar perdidamente, porque apenas julgam pelas aparências, e que, obrigados a viver com as pessoas amadas, não tardam a reconhecer que só experimentaram um encantamento material! Não basta uma pessoa estar enamorada de outra que lhe agrada e em quem supõe belas qualidades. Vivendo realmente com ela é que poderá apreciá-la. Tanto assim que, em muitas uniões, que a princípio parecem destinadas a nunca ser simpáticas, acabam os que as constituíram, depois de se haverem estudado bem e de bem se conhecerem, por votar-se, reciprocamente, duradouro e terno amor, porque assente na estima! Cumpre não se esqueça de que é o Espírito quem ama e não o corpo, de sorte que, dissipada a ilusão material, o Espírito vê a realidade." "Duas espécies há de afeição: a do corpo e a da alma, acontecendo com freqüência tomar-se uma pela outra. Quando pura e simpática, a afeição da alma é duradoura; efêmera a do corpo. Daí vem que, muitas vezes, os que julgavam amar-se com eterno amor passam a odiar-se, desde que a ilusão se desfaça.', 'rascunho'),
  (940, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Não constitui igualmente fonte de dissabores, tanto mais amargos quanto envenenam toda a existência, a falta de simpatia entre seres destinados a viver juntos?', 'Amaríssimos, com efeito. Essa, porém, é uma das infelicidades de que sois, as mais das vezes, a causa principal. Em primeiro lugar, o erro é das vossas leis. Julgas, porventura, que Deus te constranja a permanecer junto dos que te desagradam? Depois, nessas uniões, ordinariamente buscais a satisfação do orgulho e da ambição, mais do que a ventura de uma afeição mútua. Sofreis então as conseqüências dos vossos prejuízos." a) — Mas, nesse caso, não há quase sempre uma vítima inocente? "Há e para ela é uma dura expiação. Mas, a responsabilidade da sua desgraça recairá sobre os que lhe tiverem sido os causadores. Se a luz da verdade já lhe houver penetrado a alma, em sua fé no futuro haurirá consolação. Todavia, à medida que os preconceitos se enfraquecerem, as causas dessas desgraças íntimas também desaparecerão.', 'rascunho'),
  (941, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Para muitas pessoas, o temor da morte é uma causa de perplexidade. Donde lhes vêm esse temor, tendo elas diante de si o futuro?', 'Falece-lhes fundamento para semelhante temor. Mas, que queres! se procuram persuadi-las, quando crianças, de que há um inferno e um paraíso e que mais certo é irem para o inferno, visto que também lhes disseram que o que está na Natureza constitui pecado mortal para a alma! Sucede então que, tornadas adultas, essas pessoas, se algum juízo têm, não podem admitir tal coisa e se fazem atéias, ou materialistas. São assim levadas a crer que, além da vida presente, nada mais há. Quanto aos que persistiram nas suas crenças da infância, esses temem aquele fogo eterno que os queimará sem os consumir." "Ao justo, nenhum temor inspira a morte, porque, com a fé, tem ele a certeza do futuro. A esperança fá-lo contar com uma vida melhor; e a caridade, a cuja lei obedece, lhe dá a segurança de que, no mundo para onde terá de ir, nenhum ser encontrará cujo olhar lhe seja de temer." O homem carnal, mais preso à vida corpórea do que à vida espiritual, tem, na Terra, penas e gozos materiais. Sua felicidade consiste na satisfação fugaz de todos os seus desejos. Sua alma, constantemente preocupada e angustiada pelas vicissitudes da vida, se conserva numa ansiedade e numa tortura perpétuas. A morte o assusta, porque ele duvida do futuro e porque tem de deixar no mundo todas as suas afeições e esperanças. O homem moral, que se colocou acima das necessidades factícias criadas pelas paixões, já neste mundo experimenta gozos que o homem material desconhece. A moderação de seus desejos lhe dá ao Espírito calma e serenidade. Ditoso pelo bem que faz, não há para ele decepções e as contrariedades lhe deslizam por sobre a alma, sem nenhuma impressão dolorosa deixarem.', 'rascunho'),
  (942, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Pessoas não haverá que achem um tanto banais esses conselhos para ser-se feliz na Terra; que neles vejam o que chamam lugares comuns, sediças verdades; e que digam, que, afinal, o segredo para ser-se feliz consiste em saber cada um suportar a sua desgraça?', 'Há as que isso dizem e em grande número. Mas, muitas se parecem com certos doentes a quem o médico prescreve a dieta; desejariam curar-se sem remédios e continuando a apanhar indigestões.', 'rascunho'),
  (943, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Donde nasce o desgosto da vida, que, sem motivos plausíveis, se apodera de certos indivíduos?', 'Efeito da ociosidade, da falta de fé e, também, da saciedade." "Para aquele que usa de suas faculdades com fim útil e de acordo com as suas aptidões naturais, o trabalho nada tem de árido e a vida se escoa mais rapidamente. Ele lhe suporta as vicissitudes com tanto mais paciência e resignação, quanto obra com o fito da felicidade mais sólida e mais durável que o espera.', 'rascunho'),
  (944, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Tem o homem o direito de dispor da sua vida? 302 – Allan Kar dec', 'Não; só a Deus assiste esse direito. O suicídio voluntário importa numa transgressão desta lei." a) — Não é sempre voluntário o suicídio? "O louco que se mata não sabe o que faz.', 'rascunho'),
  (945, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Que se deve pensar do suicídio que tem como causa o desgosto da vida?', 'Insensatos! Por que não trabalhavam? A existência não lhes teria sido tão pesada.', 'rascunho'),
  (946, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'E do suicídio cujo fim é fugir, aquele que o comete, às misérias e às decepções deste mundo?', 'Pobres Espíritos, que não têm a coragem de suportar as misérias da existência! Deus ajuda aos que sofrem e não aos que carecem de energia e de coragem. As tribulações da vida são provas ou expiações. Felizes os que as suportam sem se queixar, porque serão recompensados! Ai, porém, daqueles que esperam a salvação do que, na sua impiedade, chamam acaso, ou fortuna! O acaso, ou a fortuna, para me servir da linguagem deles, podem, com efeito, favorecê-los por um momento, mas para lhes fazer sentir mais tarde, cruelmente, a vacuidade dessas palavras." a) — Os que hajam conduzido o desgraçado a esse ato de desespero sofrerão as conseqüências de tal proceder? "Oh! esses, ai deles! Responderão como por um assassínio.', 'rascunho'),
  (947, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Pode ser considerado suicida aquele que, a braços com a maior penúria, se deixa morrer de fome?', 'É um suicídio, mas os que lhe foram causa, ou que teriam podido impedi- lo, são mais culpados do que ele, a quem a indulgência espera. Todavia, não penseis que seja totalmente absolvido, se lhe faltaram firmeza e perseverança e se não usou de toda a sua inteligência para sair do atoleiro. Ai dele, sobretudo, se o seu desespero nasce do orgulho. Quero dizer: se for quais homens em quem o orgulho anula os recursos da inteligência, que corariam de dever a existência ao trabalho de suas mãos e que preferem morrer de fome a renunciar ao que chamam sua posição social! Não haverá mil vezes mais grandeza e dignidade em lutar contra a adversidade, em afrontar a crítica de um mundo fútil e egoísta, que só tem boa vontade para com aqueles a quem nada falta e que vos volta as costas assim precisais dele? Sacrificar a vida à consideração desse mundo é estultícia, porquanto ele a isso nenhum apreço dá.', 'rascunho'),
  (948, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'É tão reprovável, como o que tem por causa o desespero, o suicídio daquele que procura escapar à vergonha de uma ação má?', 'O suicídio não apaga a falta. Ao contrário, em vez de uma, haverá duas. Quando se teve a coragem de praticar o mal, é preciso ter-se a de lhe sofrer as conseqüências. Deus, que julga, pode, conforme a causa, abrandar os rigores de sua justiça.', 'rascunho'),
  (949, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Será desculpável o suicídio, quando tenha por fim obstar a que a vergonha caia sobre os filhos, ou sobre a família?', 'O que assim procede não faz bem. Mas, como pensa que o faz, Deus lhe leva isso em conta, pois que é uma expiação que ele se impõe a si mesmo. A intenção lhe atenua a falta; entretanto, nem por isso deixa de haver falta. Demais, eliminai da vossa sociedade os abusos e os preconceitos e deixará de haver desses suicídios." Aquele que tira a si mesmo a vida, para fugir à vergonha de uma ação má, prova que dá mais apreço à estima dos homens do que à de Deus, visto que volta para a vida espiritual carregado de suas iniqüidades, tendo-se privado dos meios de repará-las durante a vida corpórea. Deus, geralmente, é menos inexorável do que os homens. Perdoa aos que sinceramente se arrependem e atende à reparação. O suicida nada repara.', 'rascunho'),
  (950, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Que pensar daquele que se mata, na esperança de chegar mais depressa a uma vida melhor?', 'Outra loucura! Que faça o bem e mais certo estará de lá chegar, pois, matando-se, retarda a sua entrada num mundo melhor e terá que pedir lhe seja permitido voltar, para concluir a vida a que pôs termo sob o influxo de uma idéia falsa. Uma falta, seja qual for, jamais abre a ninguém o santuário dos eleitos.', 'rascunho'),
  (951, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Não é, às vezes, meritório o sacrifício da vida, quando aquele que o faz visa salvar a de outrem, ou ser útil aos seus semelhantes?', 'Isso é sublime, conforme a intenção, e, em tal caso, o sacrifício da vida não constitui suicídio. Mas, Deus se opõe a todo sacrifício inútil e não o pode ver de bom grado, se tem o orgulho a manchá-lo. Só o desinteresse torna meritório o sacrifício e, não raro, quem o faz guarda oculto um pensamento, que lhe diminui o valor aos olhos de Deus." Todo sacrifício que o homem faça à custa da sua própria felicidade é um ato soberanamente meritório aos olhos de Deus, porque resulta da prática da lei de caridade. Ora, sendo a vida o bem terreno a que maior apreço dá o homem, não comete atentado o que a ela renuncia pelo bem de seus semelhantes: cumpre um sacrifício. Mas, antes de o cumprir, deve refletir sobre se sua vida não será mais útil do que sua morte.', 'rascunho'),
  (952, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Comete suicídio o homem que perece vítima de paixões que ele sabia lhe haviam de apressar o fim, porém a que já não podia resistir, por havê-las o hábito mudado em verdadeiras necessidades físicas?', 'É um suicídio moral. Não percebeis que, nesse caso, o homem é duplamente culpado? Há nele então falta de coragem e bestialidade, acrescidas do esquecimento de Deus." a) — Será mais, ou menos, culpado do que o que tira a si mesmo a vida por desespero? "É mais culpado, porque tem tempo de refletir sobre o seu suicídio. Naquele que o faz instantaneamente, há, muitas vezes, uma espécie de desvairamento, que alguma coisa tem da loucura. O outro será muito mais punido, 304 – Allan Kar dec por isso que as penas são proporcionadas sempre à consciência que o culpado tem das faltas que comete.', 'rascunho'),
  (953, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Quando uma pessoa vê diante de si um fim inevitável e horrível, será culpada se abreviar de alguns instantes os seus sofrimentos, apressando voluntariamente sua morte?', 'É sempre culpado aquele que não aguarda o termo que Deus lhe marcou para a existência. E quem poderá estar certo de que, malgrado às aparências, esse termo tenha chegado; de que um socorro inesperado não venha no último momento?" a) — Concebe-se que, nas circunstâncias ordinárias, o suicídio seja condenável; mas, estamos figurando o caso em que a morte é inevitável e em que a vida só é encurtada de alguns instantes. "É sempre uma falta de resignação e de submissão à vontade do Criador." b) — Quais, nesse caso, as conseqüências de tal ato? "Uma expiação proporcionada, como sempre, à gravidade da falta, de acordo com as circunstâncias.', 'rascunho'),
  (954, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Será condenável uma imprudência que compromete a vida sem necessidade?', 'Não há culpabilidade, em não havendo intenção, ou consciência perfeita da prática do mal.', 'rascunho'),
  (955, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Podem ser consideradas suicidas e sofrem as conseqüências de um suicídio as mulheres que, em certos países, se queimam voluntariamente sobre os corpos dos maridos?', 'Obedecem a um preconceito e, muitas vezes, mais à força do que por vontade. Julgam cumprir um dever e esse não é o caráter do suicídio. Encontram desculpa na nulidade moral que as caracteriza, em a sua maioria, e na ignorância em que se acham. Esses usos bárbaros e estúpidos desaparecem com o advento da civilização.', 'rascunho'),
  (956, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Alcançam o fim objetivado aqueles que, não podendo conformar-se com a perda de pessoas que lhes eram caras, se matam na esperança de ir juntar-se-lhes?', 'Muito diverso do que esperam é o resultado que colhem. Em vez de se reunirem ao que era objeto de suas afeições, dele se afastam por longo tempo, pois não é possível que Deus recompense um ato de covardia e o insulto que lhe fazem com o duvidarem da sua providência. Pagarão esse instante de loucura com aflições maiores do que as que pensaram abreviar e não terão, para compensá-las, a satisfação que esperavam." (934 e seguintes)', 'rascunho'),
  (957, 'Parte Quarta — Das esperanças e consolações', 'Capítulo I — Das penas e gozos terrestres', 'Quais, em geral, com relação ao estado do Espírito, as conseqüências do suicídio?', 'Muito diversas são as conseqüências do suicídio. Não há penas determinadas e, em todos os casos, correspondem sempre às causas que o produziram. Há, porém, uma conseqüência a que o suicida não pode escapar; é o desapontamento. Mas, a sorte não é a mesma para todos; depende das circunstâncias. Alguns expiam a falta imediatamente, outros em nova existência, que será pior do que aquela cujo curso interromperam." A observação, realmente, mostra que os efeitos do suicídio não são idênticos. Alguns há, porém, comuns a todos os casos de morte violenta e que são a conseqüência da interrupção brusca da vida. Há, primeiro, a persistência mais prolongada e tenaz do laço que une o Espírito ao corpo, por estar quase sempre esse laço na plenitude da sua força no momento em que é partido, ao passo que, no caso de morte natural, ele se enfraquece gradualmente e muitas vezes se desfaz antes que a vida se haja extinguido completamente. As conseqüências deste estado de coisas são o prolongamento da perturbação espiritual, seguindo-se à ilusão em que, durante mais ou menos tempo, o Espírito se conserva de que ainda pertence ao número dos vivos. (l55 e 165) A afinidade que permanece entre o Espírito e o corpo produz, nalguns suicidas, uma espécie de repercussão do estado do corpo no Espírito, que, assim, a seu mau grado, sente os efeitos da decomposição, donde lhe resulta uma sensação cheia de angústias e de horror, estado esse que também pode durar pelo tempo que devia durar a vida que sofreu interrupção. Não é geral este efeito; mas, em caso algum, o suicida fica isento das conseqüências da sua falta de coragem e, cedo ou tarde, expia, de um modo ou de outro, a culpa em que incorreu. Assim é que certos Espíritos, que foram muito desgraçados na Terra, disseram ter-se suicidado na existência precedente e submetido voluntariamente a novas provas, para tentarem suportá-las com mais resignação. Em alguns, verifica-se uma espécie de ligação à matéria, de que inutilmente procuram desembaraçar-se, a fim de voarem para mundos melhores, cujo acesso, porém, se lhes conserva interdito. A maior parte deles sofre o pesar de haver feito uma coisa inútil, pois que só decepções encontram. A religião, a moral, todas as filosofias condenam o suicídio como contrário às leis da Natureza. Todas nos dizem, em princípio, que ninguém tem o direito de abreviar voluntariamente a vida. Entretanto, por que não se tem esse direito? Por que não é livre o homem de pôr termo aos seus sofrimentos? Ao Espiritismo estava reservado demonstrar, pelo exemplo dos que sucumbiram, que o suicídio não é uma falta, somente por constituir infração de uma lei moral, consideração de pouco peso para certos indivíduos, mas também um ato estúpido, pois que nada ganha quem o pratica, antes o contrário é o que se dá, como no-lo ensinam, não a teoria, porém os fatos que ele nos põe sob as vistas. 306 – Allan Kar dec', 'rascunho'),
  (958, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Por que tem o homem, instintivamente, horror ao nada?', 'Porque o nada não existe.', 'rascunho'),
  (959, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Donde nasce, para o homem, o sentimento instintivo da vida futura?', 'Já temos dito: antes de encarnar, o Espírito conhecia todas essas coisas e a alma conserva vaga lembrança do que sabe e do que viu no estado espiritual." Em todos os tempos, o homem se preocupou com o seu futuro para lá do túmulo e isso é muito natural. Qualquer que seja a importância que ligue à vida presente, não pode ele furtar-se a considerar quanto essa vida é curta e, sobretudo, precária, pois que a cada instante está sujeita a interromper-se, nenhuma certeza lhe sendo permitida acerca do dia seguinte. Que será dele, após o instante fatal? Questão grave esta, porquanto não se trata de alguns anos apenas, mas da eternidade. Aquele que tem de passar longo tempo, em país estrangeiro, se preocupa com a situação em que lá se achará. Como, então, não nos havia de preocupar a em que nos veremos, deixando este mundo, uma vez que é para sempre? A idéia do nada tem qualquer coisa que repugna à razão. O homem que mais despreocupado seja durante a vida, em chegando o momento supremo, pergunta a si mesmo o que vai ser dele e, sem o querer, espera. Crer em Deus, sem admitir a vida futura, fora um contra-senso. O sentimento de uma existência melhor reside no foro íntimo de todos os homens e não é possível que Deus aí o tenha colocado em vão. A vida futura implica a conservação da nossa individualidade, após a morte. Com efeito, que nos importaria sobreviver ao corpo, se a nossa essência moral houvesse de perder-se no oceano do infinito? As conseqüências, para nós, seriam as mesmas que se tivéssemos de nos sumir no nada.', 'rascunho'),
  (960, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Donde se origina a crença, com que deparamos entre todos os povos, na existência de penas e recompensas porvindouras?', 'É sempre a mesma coisa: pressentimento da realidade, trazido ao homem pelo Espírito nele encarnado. Porque, sabei-o bem, não é debalde que uma voz interior vos fala. O vosso erro consiste em não lhe prestardes bastante atenção. Melhores vos tornaríeis, se nisso pensásseis muito, e muitas vezes.', 'rascunho'),
  (961, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Qual o sentimento que domina a maioria dos homens no momento da morte: a dúvida, o temor, ou a esperança?', 'A dúvida, nos cépticos empedernidos; o temor, nos culpados; a esperança, nos homens de bem.', 'rascunho'),
  (962, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Como pode haver cépticos, uma vez que a alma traz ao homem o sentimento das coisas espirituais?', 'Eles são em número muito menor do que se julga. Muitos se fazem de espíritos fortes, durante a vida, somente por orgulho. No momento da morte, porém, deixam de ser tão fanfarrões." A responsabilidade dos nossos atos é a conseqüência da realidade da vida futura. Dizem-nos a razão e a justiça que, na partilha da felicidade a que todos aspiram, não podem estar confundidos os bons e os maus. Não é possível que Deus queira que uns gozem, sem trabalho, de bens que outros só alcançam com esforço e perseverança. A idéia que, mediante a sabedoria de suas leis, Deus nos dá de sua justiça e de sua bondade não nos permite acreditar que o justo e o mau estejam na mesma categoria a seus olhos, nem duvidar de que recebam, algum dia, um a recompensa, o castigo o outro, pelo bem ou pelo mal que tenham feito. Por isso é que o sentimento inato que temos da justiça nos dá a intuição das penas e recompensas futuras.', 'rascunho'),
  (963, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Com cada homem, pessoalmente, Deus se ocupa? Não é ele muito grande e nós muito pequeninos para que cada indivíduo em particular tenha, a seus olhos, alguma importância?', 'Deus se ocupa com todos os seres que criou, por mais pequeninos que sejam. Nada, para a sua bondade, é destituído de valor.', 'rascunho'),
  (964, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Mas, será necessário que Deus atente em cada um dos nossos atos, para nos recompensar ou punir? Esses atos não são, na sua maioria, insignificantes para ele? 308 – Allan Kar dec', 'Deus tem suas leis a regerem todas as vossas ações. Se as violais, vossa é a culpa. Indubitavelmente, quando um homem comete um excesso qualquer, Deus não profere contra ele um julgamento, dizendo-lhe, por exemplo: Foste guloso, vou punir-te. Ele traçou um limite; as enfermidades e muitas vezes a morte são a conseqüência dos excessos. Eis aí a punição; é o resultado da infração da lei. Assim em tudo." Todas as nossas ações estão submetidas às leis de Deus. Nenhuma há, por mais insignificante que nos pareça, que não possa ser uma violação daquelas leis. Se sofremos as conseqüências dessa violação, só nos devemos queixar de nós mesmos, que desse modo nos fazemos os causadores da nossa felicidade, ou da nossa infelicidade futuras. Esta verdade se torna evidente por meio do apólogo seguinte: " Um pai deu a seu filho educação e instrução, isto é, os meios de se guiar. Cede-lhe um campo para que o cultive e lhe diz: Aqui estão a regra que deves seguir e todos os instrumentos necessários a tornares fértil este campo e assegurares a tua existência. Dei-te a instrução, para compreenderes esta regra. Se a seguires, teu campo produzirá muito e te proporcionará o repouso na velhice. Se a desprezares, nada produzirá e morrerás de fome. Dito isso, deixa-o proceder livremente." Não é verdade que esse campo produzirá na razão dos cuidados que forem dispensados à sua cultura e que toda negligência redundará em prejuízo da colheita? Na velhice, portanto, o filho será ditoso, ou desgraçado, conforme haja seguido ou não a regra que seu pai lhe traçou. Deus ainda é mais previdente, pois que nos adverte, a cada instante, de que estamos fazendo bem ou mal. Envia-nos os Espíritos para nos inspirarem, porém não os escutamos. Há mais esta diferença: Deus faculta sempre ao homem, concedendo-lhe novas existências, recursos para reparar seus erros passados, enquanto ao filho de quem falamos, se empregou mal o seu tempo, nenhum recurso resta.', 'rascunho'),
  (965, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Têm alguma coisa de material as penas e gozos da alma depois da morte?', 'Não podem ser materiais, di-lo o bom-senso, pois que a alma não é matéria. Nada têm de carnal essas penas e esses gozos; entretanto, são mil vezes mais vivos do que os que experimentais na Terra, porque o Espírito, uma vez liberto, é mais impressionável. Então, já a matéria não lhe embota as sensações." (237 a 257)', 'rascunho'),
  (966, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Por que das penas e gozos da vida futura faz o homem, às vezes, tão grosseira e absurda idéia?', 'Inteligência que ainda se não desenvolveu bastante. Compreende a criança as coisas como o adulto? Isso, ao demais, depende também do que se lhe ensinou: aí é que há necessidade de uma reforma." "Muitíssimo incompleta é a vossa linguagem, para exprimir o que está fora de vós. Teve-se então que recorrer a comparações e tomastes como realidade as imagens e figuras que serviram para essas comparações. À medida, porém, que o homem se instrui, melhor vai compreendendo o que a sua linguagem não pode exprimir.', 'rascunho'),
  (967, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Em que consiste a felicidade dos bons Espíritos?', 'Em conhecerem todas as coisas; em não sentirem ódio, nem ciúme, nem inveja, nem ambição, nem qualquer das paixões que ocasionam a desgraça dos homens. O amor que os une lhes é fonte de suprema felicidade. Não experimentam as necessidades, nem os sofrimentos, nem as angústias da vida material. São felizes pelo bem que fazem. Contudo, a felicidade dos Espíritos é proporcional à elevação de cada um. Somente os puros Espíritos gozam, é exato, da felicidade suprema, mas nem todos os outros são infelizes. Entre os maus e os perfeitos há uma infinidade de graus em que os gozos são relativos ao estado moral. Os que já estão bastante adiantados compreendem a ventura dos que os precederam e aspiram a alcançá-la. Mas, esta aspiração lhes constitui uma causa de emulação, não de ciúme. Sabem que deles depende o consegui-la e para a conseguirem trabalham, porém com a calma da consciência tranqüila e ditosos se consideram por não terem que sofrer o que sofrem os maus.', 'rascunho'),
  (968, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Citais, entre as condições da felicidade dos bons Espíritos, a ausência das necessidades materiais. Mas, a satisfação dessas necessidades não representa para o homem uma fonte de gozos?', 'Sim, gozo do animal. Quando não podes satisfazer a essas necessidades, passas por uma tortura.', 'rascunho'),
  (969, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Questão 969', 'Que se deve entender quando é dito que os Espíritos puros se acham reunidos no seio de Deus e ocupados em lhe entoar louvores? É uma alegoria indicativa da inteligência que eles têm das perfeições de Deus, porque o vêem e compreendem, mas que, como muitas outras, não se deve tomar ao pé da letra. Tudo em a Natureza, desde o grão de areia, canta, isto é, proclama o poder, a sabedoria e a bondade de Deus. Não creias, todavia, que os Espíritos bem-aventurados estejam em contemplação por toda a eternidade. Seria uma bem-aventurança estúpida e monótona. Fora, além disso, a felicidade do egoísta, porquanto a existência deles seria uma inutilidade sem-termo. Estão isentos das tribulações da vida corpórea: já é um gozo. Depois, como dissemos, conhecem e sabem todas as coisas; dão útil emprego à inteligência que adquiriram, auxiliando os progressos dos outros Espíritos. Essa a sua ocupação, que ao mesmo tempo é um gozo.”', 'rascunho'),
  (970, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Em que consistem os sofrimentos dos Espíritos inferiores?', 'São tão variados como as causas que os determinam e proporcionados ao grau de inferioridade, como os gozos o são ao de superioridade. Podem resumir-se assim: Invejarem o que lhes falta para ser felizes e não obterem; verem a felicidade e não na poderem alcançar; pesar, ciúme, raiva, desespero, motivados pelo que os impede de ser ditosos; remorsos, ansiedade moral indefinível. Desejam todos os gozos e não os podem satisfazer: eis o que os tortura.', 'rascunho'),
  (971, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'É sempre boa a influência que os Espíritos exercem uns sobre os outros?', 'Sempre boa, está claro, da parte dos bons Espíritos. Os Espíritos perversos, esses procuram desviar da senda do bem e do arrependimento os que lhes 310 – Allan Kar dec parecem suscetíveis de se deixarem levar e que são, muitas vezes, os que eles mesmos arrastaram ao mal durante a vida terrena." a) — Assim, a morte não nos livra da tentação? "Não, mas a ação dos maus Espíritos é sempre menor sobre os outros Espíritos do que sobre os homens, porque lhes falta o auxílio das paixões materiais.', 'rascunho'),
  (972, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Como procedem os maus Espíritos para tentar os outros Espíritos, não podendo jogar com as paixões?', 'As paixões não existem materialmente, mas existem no pensamento dos Espíritos atrasados. Os maus dão pasto a esses pensamentos, conduzindo suas vítimas aos lugares onde se lhes ofereça o espetáculo daquelas paixões e de tudo o que as possa excitar." a) — Mas, de que servem essas paixões, se já não têm objeto real? "Nisso precisamente é que lhes está o suplício: o avarento vê ouro que lhe não é dado possuir; o devasso, orgias em que não pode tomar parte; o orgulhoso, honras que lhe causam inveja e de que não pode gozar.', 'rascunho'),
  (973, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Quais os sofrimentos maiores a que os Espíritos maus se vêem sujeitos?', 'Não há descrição possível das torturas morais que constituem a punição de certos crimes. Mesmo o que as sofre teria dificuldade em vos dar delas uma idéia. Indubitavelmente, porém, a mais horrível consiste em pensarem que estão condenados sem remissão." Das penas e gozos da alma após a morte forma o homem idéia mais ou menos elevada, conforme o estado de sua inteligência. Quanto mais ele se desenvolve, tanto mais essa idéia se apura e se escoima da matéria; compreende as coisas de um ponto de vista mais racional, deixando de tomar ao pé da letra as imagens de uma linguagem figurada. Ensinando-nos que a alma é um ser todo espiritual, a razão, mais esclarecida, nos diz, por isso mesmo, que ela não pode ser atingida pelas impressões que apenas sobre a matéria atuam. Não se segue, porém, daí que esteja isenta de sofrimentos, nem que não receba o castigo de suas faltas. As comunicações espíritas tiveram como resultado mostrar o estado futuro da alma, não mais em teoria, porém na realidade. Põem-nos diante dos olhos todas as peripécias da vida de além-túmulo. Ao mesmo tempo, entretanto, no-las mostram como conseqüências perfeitamente lógicas da vida terrestre e, embora despojadas do aparato fantástico que a imaginação dos homens criou, não são menos pessoais para os que fizeram mau uso de suas faculdades. Infinita é a variedade dessas conseqüências. Mas, em tese geral, pode-se dizer: cada um é punido por aquilo em que pecou. Assim é que uns o são pela visão incessante do mal que fizeram; outros, pelo pesar, pelo temor, pela vergonha, pela dúvida, pelo insulamento, pelas trevas, pela separação dos entes que lhes são caros, etc.', 'rascunho'),
  (974, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Donde procede a doutrina do fogo eterno?', 'Imagem, semelhante a tantas outras, tomada como realidade." a) — Mas, o temor desse fogo não produzirá bom resultado? "Vede se serve de freio, mesmo entre os que o ensinam. Se ensinardes coisas que mais tarde a razão venha a repelir, causareis uma impressão que não será duradoura, nem salutar." Impotente para, na sua linguagem, definir a natureza daqueles sofrimentos, o homem não encontrou comparação mais enérgica do que a do fogo, pois, para ele, o fogo é o tipo do mais cruel suplício e o símbolo da ação mais violenta. Por isso é que a crença no fogo eterno data da mais remota antiguidade, tendo-a os povos modernos herdado dos mais antigos. Por isso também é que o homem diz, em sua linguagem figurada: o fogo das paixões; abrasar de amor, de ciúme, etc.', 'rascunho'),
  (975, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Os Espíritos inferiores compreendem a felicidade do justo?', 'Sim, e isso lhes é um suplício, porque compreendem que estão dela privados por sua culpa. Daí resulta que o Espírito, liberto da matéria, aspira à nova vida corporal, pois que cada existência, se for bem empregada, abrevia um tanto a duração desse suplício. É então que procede à escolha das provas por meio das quais possa expiar suas faltas. Porque, ficai sabendo, o Espírito sofre por todo o mal que praticou, ou de que foi causa voluntária, por todo o bem que houvera podido fazer e não fez e por todo o mal que decorra de não haver feito o bem." "Para o Espírito errante, já não há véus. Ele se acha como tendo saído de um nevoeiro e vê o que o distancia da felicidade. Mais sofre então, porque compreende quanto foi culpado. Não tem mais ilusões: vê as coisas na sua realidade." Na erraticidade, o Espírito descortina, de um lado, todas as suas existências passadas; de outro, o futuro que lhe está prometido e percebe o que lhe falta para atingi-lo. É qual viajor que chega ao cume de uma montanha: vê o caminho que percorreu e o que lhe resta percorrer, a fim de chegar ao fim da sua jornada.', 'rascunho'),
  (976, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'O espetáculo dos sofrimentos dos Espíritos inferiores não constitui, para os bons, uma causa de aflição e, nesse caso, que fica sendo a felicidade deles, se é assim turbada?', 'Não constitui motivo de aflição, pois que sabem que o mal terá fim. Auxiliam os outros a se melhorarem e lhes estendem as mãos. Essa a ocupação deles, ocupação que lhes proporciona gozo quando são bem-sucedidos." a) — Isto se concebe da parte de Espíritos estranhos ou indiferentes. Mas o espetáculo das tristezas e dos sofrimentos daqueles a quem amaram na Terra não lhes perturba a felicidade? "Se não vissem esses sofrimentos, é que eles vos seriam estranhos depois da morte. Ora, a religião vos diz que as almas vos vêem. Mas, eles consideram de outro ponto de vista os vossos sofrimentos. Sabem que estes são úteis ao vosso progresso, se os suportardes com resignação. Afligem-se, portanto, muito mais com a falta de ânimo que vos retarda, do que com os sofrimentos considerados em si mesmos, todos passageiros.', 'rascunho'),
  (977, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Não podendo os Espíritos ocultar reciprocamente seus pensamentos e sendo conhecidos todos os atos da vida, dever-se-á deduzir que o culpado está perpetuamente em presença de sua vítima?', 'Não pode ser de outro modo, di-lo o bom-senso." 312 – Allan Kar dec a) — Serão um castigo para o culpado essa divulgação de todos os nossos atos reprováveis e a presença constante dos que deles foram vítimas? "Maior do que se pensa, mas tão-somente até que o culpado tenha expiado suas faltas, quer como Espírito, quer como homem, em novas existências corpóreas." Quando nos achamos no mundo dos Espíritos, estando patente todo o nosso passado, o bem e o mal que houvermos feito serão igualmente conhecidos. Em vão, aquele que haja praticado o mal tentará escapar ao olhar de suas vítimas: a presença inevitável destas lhe será um castigo e um remorso incessante, até que haja expiado seus erros, ao passo que o homem de bem por toda parte só encontrará olhares amigos e benevolentes. Para o mau, não há maior tormento, na Terra, do que a presença de suas vítimas, razão pela qual as evita continuamente. Que será quando, dissipada a ilusão das paixões, compreender o mal que fez, vir patenteados os seus atos mais secretos, desmascarada a sua hipocrisia e não puder subtrair-se à visão delas? Enquanto a alma do homem perverso é presa da vergonha, do pesar e do remorso, a do justo goza perfeita serenidade.', 'rascunho'),
  (978, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'A lembrança das faltas que a alma, quando imperfeita, tenha cometido, não lhe turba a felicidade, mesmo depois de se haver purificado?', 'Não, porque resgatou suas faltas e saiu vitoriosa das provas a que se submetera para esse fim.', 'rascunho'),
  (979, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Não serão, para a alma, causa de penosa apreensão, que lhe altera a felicidade, as provas por que ainda tenha de passar para acabar a sua purificação?', 'Para a alma ainda maculada, são. Daí vem que ela não pode gozar de felicidade perfeita, senão quando esteja completamente pura. Para aquela, porém, que já se elevou, nada tem de penoso o pensar nas provas que ainda haja de sofrer." Goza da felicidade a alma que chegou a um certo grau de pureza. Domina-a um sentimento de grata satisfação. Sente-se feliz por tudo o que vê, por tudo o que a cerca. Levanta-se-lhe o véu que encobria os mistérios e as maravilhas da Criação e as perfeições divinas em todo o esplendor lhe aparecem.', 'rascunho'),
  (980, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'O laço de simpatia que une os Espíritos da mesma ordem constitui para eles uma fonte de felicidade?', 'Os Espíritos entre os quais há recíproca simpatia para o bem encontram na sua união um dos maiores gozos, visto que não receiam vê-la turbada pelo egoísmo. Formam, no mundo inteiramente espiritual, famílias pela identidade de sentimentos, consistindo nisto a felicidade espiritual, do mesmo modo que no vosso mundo vos grupais em categorias e experimentais certo prazer quando vos achais reunidos. Na afeição pura e sincera que cada um vota aos outros e de que é por sua vez objeto, têm eles um manancial de felicidade, porquanto lá não há falsos amigos, nem hipócritas." Das primícias dessa felicidade goza o homem na Terra, quando se lhe deparam almas com as quais pode confundir-se numa união pura e santa. Em uma vida mais purificada, inefável e ilimitado será esse gozo, pois aí ele só encontrará almas simpáticas, que o egoísmo não tornará frias. Porque, em a Natureza, tudo é amor: o egoísmo é que o mata.', 'rascunho'),
  (981, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Com relação ao estado futuro do Espírito, haverá diferença entre um que, em vida, teme a morte e outro que a encara com indiferença e mesmo com alegria?', 'Muito grande pode ser a diferença. Entretanto, apaga-se com freqüência em face das causas determinantes desse temor ou desse desejo. Quer a tema, quer a deseje, pode o homem ser propelido por sentimentos muito diversos e são estes sentimentos que influem no estado do Espírito. É evidente, por exemplo, que naquele que deseja a morte, unicamente porque vê nela o termo de suas tribulações, há uma espécie de queixa contra a Providência e contra as provas que lhe cumpre suportar.', 'rascunho'),
  (982, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Será necessário que professemos o Espiritismo e creiamos nas manifestações espíritas, para termos assegurada a nossa sorte na vida futura?', 'Se assim fosse, seguir-se-ia que estariam deserdados todos os que não crêem, ou que não tiveram ensejo de esclarecer-se, o que seria absurdo. Só o bem assegura a sorte futura. Ora, o bem é sempre o bem, qualquer que seja o caminho que a ele conduza." (165-799) A crença no Espiritismo ajuda o homem a se melhorar, firmando-lhe as idéias sobre certos pontos do futuro. Apressa o adiantamento dos indivíduos e das massas, porque faculta nos inteiremos do que seremos um dia. É um ponto de apoio, uma luz que nos guia. O Espiritismo ensina o homem a suportar as provas com paciência e resignação; afasta-o dos atos que possam retardar-lhe a felicidade, mas ninguém diz que, sem ele, não possa ela ser conseguida.', 'rascunho'),
  (983, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Não experimenta sofrimentos materiais o Espírito que expia suas faltas em nova existência? Será então exato dizer-se que, depois da morte, só há para a alma sofrimentos morais?', 'É bem verdade que, quando a alma está reencarnada, as tribulações da vida são-lhe um sofrimento; mas, só o corpo sofre materialmente. "Falando de alguém que morreu, costumais dizer que deixou de sofrer. Nem sempre isto exprime a realidade. Como Espírito, está isento de dores físicas; porém, tais sejam as faltas que tenha cometido, pode estar sujeito a dores morais mais agudas e pode vir a ser ainda mais desgraçado em nova existência. O mau rico terá que pedir esmola e se verá a braços com todas as privações oriundas da miséria; o orgulhoso, com todas as humilhações: o que abusa de sua autoridade e trata com desprezo e dureza os seus subordinados se verá forçado a obedecer a um superior mais ríspido do que ele o foi. Todas as penas e tribulações da vida são expiação das faltas de outra existência, quando não a conseqüência das da vida atual. Logo que daqui houverdes saído, compreendê-lo-eis. (273, 393 e 399)" "O homem que se considera feliz na Terra, porque pode satisfazer às suas paixões, é o que menos esforços emprega para se melhorar. Muitas vezes começa a sua expiação já nessa mesma vida de efêmera felicidade, mas certamente expiará noutra existência tão material quanto aquela.', 'rascunho'),
  (984, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'As vicissitudes da vida são sempre a punição das faltas atuais? 314 – Allan Kar dec', 'Não; já dissemos: são provas impostas por Deus, ou que vós mesmos escolhestes como Espíritos, antes de encarnardes, para expiação das faltas cometidas em outra existência, porque jamais fica impune a infração das leis de Deus e, sobretudo, da lei de justiça. Se não for punida nesta existência, sê-lo-á necessariamente noutra. Eis por que um, que vos parece justo, muitas vezes sofre. É a punição do seu passado.', 'rascunho'),
  (985, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Constitui recompensa a reencarnação da alma em um mundo menos grosseiro?', 'É a conseqüência de sua depuração, porquanto, à medida que se vão depurando, os Espíritos passam a encarnar em mundos cada vez mais perfeitos, até que se tenham despojado totalmente da matéria e lavado de todas as impurezas, para eternamente gozarem da felicidade dos Espíritos puros, no seio de Deus." Nos mundos onde a existência é menos material do que neste, menos grosseiras são as necessidades e menos agudos os sofrimentos físicos. Lá, os homens desconhecem as paixões más, que, nos mundos inferiores, os fazem inimigos uns dos outros. Nenhum motivo tendo de ódio, ou de ciúme, vivem em paz, porque praticam a lei de justiça, amor e caridade. Não conhecem os aborrecimentos e cuidados que nascem da inveja, do orgulho e do egoísmo, causas do tormento da nossa existência terrestre. (l72--182)', 'rascunho'),
  (986, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Pode o Espírito, que progrediu em sua existência terrena, reencarnar alguma vez no mesmo mundo?', 'Sim; desde que não tenha logrado concluir a sua missão, pode ele próprio pedir lhe seja dado completá-la em nova existência. Mas, então, já não está sujeito a uma expiação." (l73)', 'rascunho'),
  (987, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Que sucede ao homem que, não fazendo o mal, também nada faz para libertar- se da influência da matéria?', 'Pois que nenhum passo dá para a perfeição, tem que recomeçar uma existência de natureza idêntica à precedente. Fica estacionário, podendo assim prolongar os sofrimentos da expiação.', 'rascunho'),
  (988, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Há pessoas cuja vida se escoa em perfeita calma; que, nada precisando fazer por si mesmas, se conservam isentas de cuidados. Provará essa existência ditosa que elas nada têm que expiar de existência anterior?', 'Conheces muitas dessas pessoas? Enganas-te, se pensas que as há em grande número. Não raro, a calma é apenas aparente. Talvez elas tenham escolhido tal existência, mas, quando a deixam, percebem que não lhes serviu para progredirem. Então, como o preguiçoso, lamentam o tempo perdido. Sabei que o Espírito não pode adquirir conhecimentos e elevar-se senão exercendo a sua atividade. Se adormece na indolência, não se adianta. Assemelha-se a um que (segundo os vossos usos) precisa trabalhar e que vai passear ou deitar-se, com a intenção de nada fazer. Sabei também que cada um terá que dar contas da inutilidade voluntária da sua existência, inutilidade sempre fatal à felicidade futura. Para cada um, o total dessa felicidade futura corresponde à soma do bem que tenha feito, estando o da infelicidade na proporção do mal que haja praticado e daqueles a quem haja desgraçado.', 'rascunho'),
  (989, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Pessoas há que, se bem não sejam positivamente más, tornam infelizes, pelos seus caracteres, todos os que as cercam. Que conseqüências lhes advirão disso?', 'Inquestionavelmente, essas pessoas não são boas. Expiarão suas faltas, tendo sempre diante da vista aqueles a quem infelicitaram, valendo-lhes isso por uma exprobração. Depois, noutra existência, sofrerão o que fizeram sofrer.', 'rascunho'),
  (990, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'O arrependimento se dá no estado corporal ou no estado espiritual?', 'No estado espiritual; mas, também pode ocorrer no estado corporal, quando bem compreendeis a diferença entre o bem e o mal.', 'rascunho'),
  (991, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Qual a conseqüência do arrependimento no estado espiritual?', 'Desejar o arrependido uma nova encarnação para se purificar. O Espírito compreende as imperfeições que o privam de ser feliz e por isso aspira a uma nova existência em que possa expiar suas faltas." (332-975)', 'rascunho'),
  (992, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Que conseqüência produz o arrependimento no estado corporal?', 'Fazer que, já na vida atual, o Espírito progrida, se tiver tempo de reparar suas faltas. Quando a consciência o exprobra e lhe mostra uma imperfeição, o homem pode sempre melhorar-se.', 'rascunho'),
  (993, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Não há homens que só têm o instinto do mal e são inacessíveis ao arrependimento?', 'Já te disse que todo Espírito tem que progredir incessantemente. Aquele que, nesta vida, só tem o instinto do mal, terá noutra o do bem e é para isso que renasce muitas vezes, pois preciso é que todos progridam e atinjam a meta. A diferença está somente em que uns gastam mais tempo do que outros, porque assim o querem. Aquele, que só tem o instinto do bem, já se purificou, visto que talvez tenha tido o do mal em anterior existência.', 'rascunho'),
  (994, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'O homem perverso, que não reconheceu suas faltas durante a vida, sempre as reconhece depois da morte?', 'Sempre as reconhece e, então, mais sofre, porque sente em si todo o mal que praticou, ou de que foi voluntariamente causa. Contudo, o arrependimento nem sempre é imediato. Há Espíritos que se obstinam em permanecer no mau caminho, não obstante os sofrimentos por que passam. Porém, cedo ou tarde, reconhecerão errada a senda que tomaram e o arrependimento virá. Para esclarecê-los trabalham os bons Espíritos e também vós podeis trabalhar.', 'rascunho'),
  (995, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Haverá Espíritos que, sem serem maus, se conservem indiferentes à sua sorte?', 'Há Espíritos que de coisa alguma útil se ocupam. Estão na expectativa. Mas, nesse caso, sofrem proporcionalmente. Devendo em tudo haver progresso, neles o progresso se manifesta pela dor." a) — Não desejam esses Espíritos abreviar seus sofrimentos? 316 – Allan Kar dec "Desejam-no, sem dúvida, mas falta-lhes energia bastante para quererem o que os pode aliviar. Quantos indivíduos se contam, entre vós, que preferem morrer de miséria a trabalhar?', 'rascunho'),
  (996, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Pois que os Espíritos vêem o mal que lhes resulta de suas imperfeições, como se explica que haja os que agravam suas situações e prolongam o estado de inferioridade em que se encontram, fazendo o mal como Espíritos, afastando do bom caminho os homens?', 'Assim procedem os de tardio arrependimento. Pode também acontecer que, depois de se haver arrependido, o Espírito se deixe arrastar de novo para o caminho do mal, por outros Espíritos ainda mais atrasados.', 'rascunho'),
  (997, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Vêem-se Espíritos, de notória inferioridade, acessíveis aos bons sentimentos e sensíveis às preces que por eles se fazem. Como se explica que outros Espíritos, que devêramos supor mais esclarecidos, revelem um endurecimento e um cinismo, dos quais coisa alguma consegue triunfar?', 'A prece só tem efeito sobre o Espírito que se arrepende. Com relação aos que, impelidos pelo orgulho, se revoltam contra Deus e persistem nos seus desvarios, chegando mesmo a exagerá-los, como o fazem alguns desgraçados Espíritos, a prece nada pode e nada poderá, senão no dia em que um clarão de arrependimento se produza neles." Não se deve perder de vista que o Espírito não se transforma subitamente, após a morte do corpo. Se viveu vida condenável, é porque era imperfeito. Ora, a morte não o torna imediatamente perfeito. Pode, pois, persistir em seus erros, em suas falsas opiniões, em seus preconceitos, até que se haja esclarecido pelo estudo, pela reflexão e pelo sofrimento.', 'rascunho'),
  (998, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'A expiação se cumpre no estado corporal ou no estado espiritual?', 'A expiação se cumpre durante a existência corporal, mediante as provas a que o Espírito se acha submetido e, na vida espiritual, pelos sofrimentos morais, inerentes ao estado de inferioridade do Espírito.', 'rascunho'),
  (999, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Basta o arrependimento durante a vida para que as faltas do Espírito se apaguem e ele ache graça diante de Deus?', 'O arrependimento concorre para a melhoria do Espírito, mas ele tem que expiar o seu passado." a) — Se, diante disto, um criminoso dissesse que, cumprindo-lhe, em todo caso, expiar o seu passado, nenhuma necessidade tem de se arrepender, que é o que daí lhe resultaria? "Tornar-se mais longa e mais penosa a sua expiação, desde que ele se torne obstinado no mal.', 'rascunho'),
  (1000, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Já desde esta vida poderemos ir resgatando as nossas faltas?', 'Sim, reparando-as. Mas, não creiais que as resgateis mediante algumas privações pueris, ou distribuindo em esmolas o que possuirdes, depois que morrerdes, quando de nada mais precisais. Deus não dá valor a um arrependimento estéril, sempre fácil e que apenas custa o esforço de bater no peito. A perda de um dedo mínimo, quando se esteja prestando um serviço, apaga mais faltas do que o suplício da carne suportado durante anos, com objetivo exclusivamente pessoal." "Só por meio do bem se repara o mal e a reparação nenhum mérito apresenta, se não atinge o homem nem no seu orgulho, nem nos seus interesses materiais." "De que serve, para sua justificação, que restitua, depois de morrer, os bens mal adquiridos, quando se lhe tornaram inúteis e deles tirou todo o proveito? "De que lhe serve privar-se de alguns gozos fúteis, de algumas superfluidades, se permanece integral o dano que causou a outrem?" "De que lhe serve, finalmente, humilhar-se diante de Deus se, perante os homens, conserva o seu orgulho?" (720-721)', 'rascunho'),
  (1001, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Nenhum mérito haverá em assegurarmos, para depois de nossa morte, emprego útil aos bens que possuímos?', 'Nenhum mérito não é o termo. Isso sempre é melhor do que nada. A desgraça, porém, é que aquele, que só depois de morto dá, é quase sempre mais egoísta do que generoso. Quer ter o fruto do bem, sem o trabalho de praticá-lo. Duplo proveito tira aquele que, em vida, se priva de alguma coisa: o mérito do sacrifício e o prazer de ver felizes os que lhe devem a felicidade. Mas, lá está o egoísmo a dizer-lhe: O que dás tiras aos teus gozos; e, como o egoísmo fala mais alto do que o desinteresse e a caridade, o homem guarda o que possui, pretextando suas necessidades pessoais e as exigências da sua posição! Ah! lastimai aquele que desconhece o prazer de dar; acha-se verdadeiramente privado de um dos mais puros e suaves gozos. Submetendo-o à prova da riqueza, tão escorregadia e perigosa para o seu futuro, houve Deus por bem conceder-lhe, como compensação, a ventura da generosidade, de que já neste mundo pode gozar.', 'rascunho'),
  (1002, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Que deve fazer aquele que, em artigo de morte, reconhece suas faltas, quando já não tem tempo de as reparar? Basta-lhe nesse caso arrepender-se?', 'O arrependimento lhe apressa a reabilitação, mas não o absolve. Diante dele não se desdobra o futuro, que jamais se lhe tranca?', 'rascunho'),
  (1003, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'É arbitrária ou sujeita a uma lei qualquer a duração dos sofrimentos do culpado, na vida futura?', 'Deus nunca obra caprichosamente e tudo, no Universo, se rege por leis, em que a sua sabedoria e a sua bondade se revelam.', 'rascunho'),
  (1004, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Em que se baseia a duração dos sofrimentos do culpado?', 'No tempo necessário a que se melhore. Sendo o estado de sofrimento ou de felicidade proporcionado ao grau de purificação do Espírito, a duração e a natureza de seus sofrimentos dependem do tempo que ele gaste em melhorar-se. À 318 – Allan Kar dec medida que progride e que os sentimentos se lhe depuram, seus sofrimentos diminuem e mudam de natureza.', 'rascunho'),
  (1005, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Ao Espírito sofredor, o tempo se afigura tão ou menos longo do que quando estava vivo?', 'Parece-lhe mais longo: para ele não existe o sono. Só para os Espíritos que já chegaram a certo grau de purificação, o tempo, por assim dizer, se apaga diante do infinito.', 'rascunho'),
  (1006, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Poderão durar eternamente os sofrimentos do Espírito?', 'Poderiam, se ele pudesse ser eternamente mau, isto é, se jamais se arrependesse e melhorasse, sofreria eternamente. Mas, Deus não criou seres tendo por destino permanecerem votados perpetuamente ao mal. Apenas os criou a todos simples e ignorantes, tendo todos, no entanto, que progredir em tempo mais ou menos longo, conforme decorrer da vontade de cada um. Mais ou menos tardia pode ser a vontade, do mesmo modo que há crianças mais ou menos precoces, porém, cedo ou tarde, ela aparece, por efeito da irresistível necessidade que o Espírito sente de sair da inferioridade e de se tornar feliz. Eminentemente sábia e magnânima é, pois, a lei que rege a duração das penas, porquanto subordina essa duração aos esforços do Espírito. Jamais o priva do seu livre-arbítrio: se deste faz ele mau uso, sofre as conseqüências.', 'rascunho'),
  (1007, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Haverá Espíritos que nunca se arrependem?', 'Há os de arrependimento muito tardio; porém, pretender-se que nunca se melhorarão fora negar a lei do progresso e dizer que a criança não pode tornar-se homem.', 'rascunho'),
  (1008, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Depende sempre da vontade do Espírito a duração das penas? Algumas não haverá que lhe sejam impostas por tempo determinado?', 'Sim, ao Espírito podem ser impostas penas por determinado tempo; mas, Deus, que só quer o bem de suas criaturas, acolhe sempre o arrependimento e infrutífero jamais fica o desejo que o Espírito manifeste de se melhorar.', 'rascunho'),
  (1009, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Assim, as penas impostas jamais o são por toda a eternidade?', 'Interrogai o vosso bom-senso, a vossa razão e perguntai-lhes se uma condenação perpétua, motivada por alguns momentos de erro, não seria a negação da bondade de Deus. Que é, com efeito, a duração da vida, ainda quando de cem anos, em face da eternidade? Eternidade! Compreendeis bem esta palavra? Sofrimentos, torturas sem-fim, sem esperanças, por causa de algumas faltas! O vosso juízo não repele semelhante idéia? Que os antigos tenham considerado o Senhor do Universo um Deus terrível, cioso e vingativo, concebe-se. Na ignorância em que se achavam, atribuíam à divindade as paixões dos homens. Esse, todavia, não é o Deus dos cristãos, que classifica como virtudes primordiais o amor, a caridade, a misericórdia, o esquecimento das ofensas. Poderia ele carecer das qualidades, cuja posse prescreve, como um dever, às suas criaturas? Não haverá contradição em se lhe atribuir a bondade infinita e a vingança também infinita? Dizeis que, acima de tudo, ele é justo e que o homem não lhe compreende a justiça. Mas, a justiça não exclui a bondade e ele não seria bom, se condenasse a eternas e horríveis penas a maioria das suas criaturas. Teria o direito de fazer da justiça uma obrigação para seus filhos, se lhes não desse meio de compreendê-la? Aliás, no fazer que a duração das penas dependa dos esforços do culpado não está toda a sublimidade da justiça unida à bondade? Aí é que se encontra a verdade desta sentença: ‘A cada um segundo as suas obras.’', 'rascunho'),
  (1010, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'O dogma da ressurreição da carne será a consagração da reencarnação ensinada pelos Espíritos?', 'Como quereríeis que fosse de outro modo? Conforme sucede com tantas outras, estas palavras só parecem despropositadas, no entender de algumas pessoas, porque as tomam ao pé da letra. Levam, por isso, à incredulidade. Dai-lhes uma interpretação lógica e os que chamais livres pensadores as admitirão sem dificuldades, precisamente pela razão de que refletem. Por que, não vos enganeis, esses livres pensadores o que mais pedem e desejam é crer. Têm, como os outros, ou, talvez, mais que os outros, a sede do futuro, mas não podem admitir o que a ciência desmente. A doutrina da pluralidade das existências é consentânea com a justiça de Deus; só ela explica o que, sem ela, é inexplicável. Como havíeis de pretender que o seu princípio não estivesse na própria religião?" — Assim, pelo dogma da ressurreição da carne, a própria Igreja ensina a doutrina da reencarnação? "É evidente. Demais, essa doutrina decorre de muitas coisas que têm passado despercebidas e que dentro em pouco se compreenderão neste sentido. Reconhecer-se-á em breve que o Espiritismo ressalta a cada passo do texto mesmo das Escrituras sagradas. Os Espíritos, portanto, não vêm subverter a religião, como alguns o pretendem. Vêm, ao contrário, confirmá-la, sancioná-la por provas irrecusáveis. Como, porém, são chegados os tempos de não mais empregarem linguagem figurada, eles se exprimem sem alegorias e dão às coisas sentido claro e preciso, que não possa estar sujeito a qualquer interpretação falsa. Eis por que, daqui a algum tempo, muito maior será do que é hoje o número de pessoas sinceramente religiosas e crentes.', 'rascunho'),
  (1012, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Haverá no Universo lugares circunscritos para as penas e gozos dos Espíritos, segundo seus merecimentos?', 'Já respondemos a esta pergunta. As penas e os gozos são inerentes ao grau de perfeição dos Espíritos. Cada um tira de si mesmo o princípio de sua felicidade ou de sua desgraça. E como eles estão por toda parte, nenhum lugar circunscrito ou fechado existe especialmente destinado a uma ou outra coisa. Quanto aos encarnados, esses são mais ou menos felizes ou desgraçados, conforme é mais ou menos adiantado o mundo em que habitam." — De acordo, então, com o que vindes de dizer, o inferno e o paraíso não existem, tais como o homem os imagina? 8 "São simples alegorias: por toda parte há Espíritos ditosos e inditosos. Entretanto, conforme também já dissemos, os Espíritos de uma mesma ordem se reúnem por simpatia; mas podem reunir-se onde queiram, quando são perfeitos." A localização absoluta das regiões das penas e das recompensas só na imaginação do homem existe. Provém da sua tendência a materializar e circunscrever as coisas, cuja essência infinita não lhe é possível compreender.', 'rascunho'),
  (1013, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Que se deve entender por purgatório?', 'Dores físicas e morais: o tempo da expiação. Quase sempre, na Terra é que fazeis o vosso purgatório e que Deus vos obriga a expiar as vossas faltas." O que o homem chama purgatório é igualmente uma alegoria, devendo-se entender como tal, não um lugar determinado, porém o estado dos Espíritos imperfeitos, que se acham em expiação até alcançarem a purificação completa, que os elevará à categoria dos Espíritos bem-aventurados. Operando-se essa purificação por meio das diversas encarnações, o purgatório consiste nas provas da vida corporal. 8', 'rascunho'),
  (1014, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Como se explica que Espíritos, cuja superioridade se revela na linguagem de que usam, tenham respondido a pessoas muito sérias, a respeito do inferno e do purgatório, de conformidade com as idéias correntes?', 'É que falam uma linguagem que possa ser compreendida pelas pessoas que os interrogam. Quando estas se mostram imbuídas de certas idéias, eles evitam chocá-las muito bruscamente, a fim de lhes não ferir as convicções. Se um Espírito dissesse a um muçulmano, sem precauções oratórias, que Maomé não foi profeta, seria muito mal acolhido." — Concebe-se que assim procedam os Espíritos que nos querem instruir. Como, porém, se explica que, interrogados acerca da situação em que se achavam, alguns Espíritos tenham respondido que sofriam as torturas do inferno ou do purgatório? "Quando são inferiores e ainda não completamente desmaterializados, os Espíritos conservam uma parte de suas idéias terrenas e, para dar suas impressões, se servem dos termos que lhes são familiares. Acham-se num meio que só imperfeitamente lhes permite sondar o futuro. Essa a causa de alguns Espíritos errantes, ou recém-desencarnados, falarem como o fariam se estivessem encarnados. Inferno se pode traduzir por uma vida de provações, extremamente dolorosa, com a incerteza de haver outra melhor; purgatório, por uma vida também de provações, mas com a consciência de melhor futuro. Quando experimentas uma grande dor, não costumas dizer que sofres como um danado? Tudo isso são apenas palavras e sempre ditas em sentido figurado.', 'rascunho'),
  (1015, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Que se deve entender por — uma alma a penar?', 'Uma alma errante e sofredora, incerta de seu futuro e à qual podeis proporcionar o alívio, que muitas vezes solicita, vindo comunicar-se convosco.', 'rascunho'),
  (1016, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Em que sentido se deve entender a palavra céu?', 'Julgas que seja um lugar, como os campos Elíseos dos antigos, onde todos os bons Espíritos estão promiscuamente aglomerados, sem outra preocupação que a de gozar, pela eternidade toda, de uma felicidade passiva? Não; é o espaço universal; são os planetas, as estrelas e todos os mundos superiores, onde os Espíritos gozam plenamente de suas faculdades, sem as tribulações da vida material, nem as angústias peculiares à inferioridade.', 'rascunho'),
  (1017, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Alguns Espíritos disseram estar habitando o quarto, o quinto céus, etc. Que queriam dizer com isso?', 'Perguntando-lhes que céu habitam, é que formais idéia de muitos céus dispostos como os andares de uma casa. Eles, então, respondem de acordo com a vossa linguagem. Mas, por estas palavras — quarto e quinto céus — exprimem diferentes graus de purificação e, por conseguinte, de felicidade. É exatamente como quando se pergunta a um Espírito se está no inferno. Se for desgraçado, dirá — sim, porque, para ele, inferno é sinônimo de sofrimento. Sabe, porém, muito bem que não é uma fornalha. Um pagão diria estar no Tártaro." O mesmo ocorre com outras expressões análogas, tais como: cidade das flores, cidade dos eleitos, primeira, segunda, ou terceira esfera, etc., que apenas são alegorias usadas por alguns Espíritos, quer como figuras, quer, algumas vezes, por ignorância da realidade das coisas, e até das mais simples noções científicas. De acordo com a idéia restrita que se fazia outrora dos lugares das penas e das recompensas e, sobretudo, de acordo com a opinião de que a Terra era o centro do Universo, de que o firmamento formava uma abóbada e que havia uma região das estrelas, o céu era situado no alto e o inferno embaixo. Daí as expressões: subir ao céu, estar no mais alto dos céus, ser precipitado nos infernos. Hoje, que a Ciência demonstrou ser a Terra apenas, entre tantos milhões de outros, um dos menores mundos, sem importância especial; que traçou a história da sua formação e lhe descreveu a constituição; que provou ser infinito o espaço, não haver alto nem baixo no Universo, teve-se que renunciar a situar o céu acima das nuvens e o inferno nos lugares inferiores. Quanto ao purgatório, nenhum lugar lhe fora designado. Estava reservado ao Espiritismo dar de tudo isso a explicação mais racional, mais grandiosa e, ao mesmo tempo, mais consoladora para a Humanidade. Pode-se assim dizer que trazemos em nós mesmos o nosso inferno e o nosso paraíso. O purgatório, achamo-lo na encarnação, nas vidas corporais ou físicas.', 'rascunho'),
  (1018, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Em que sentido se devem entender estas palavras do Cristo: Meu reino não é deste mundo?', 'Respondendo assim, o Cristo falava em sentido figurado. Queria dizer que o seu reinado se exerce unicamente sobre os corações puros e desinteressados. Ele está onde quer que domine o amor do bem. Ávidos, porém, das coisas deste mundo e apegados aos bens da Terra, os homens com ele não estão.', 'rascunho'),
  (1019, 'Parte Quarta — Das esperanças e consolações', 'Capítulo II — Das penas e gozos futuros', 'Poderá jamais implantar-se na Terra o reinado do bem?', 'O bem reinará na Terra quando, entre os Espíritos que a vêm habitar, os bons predominarem, porque, então, farão que aí reinem o amor e a justiça, fonte do bem e da felicidade. Por meio do progresso moral e praticando as leis de Deus é que o homem atrairá para a Terra os bons Espíritos e dela afastará os maus. Estes, porém, não a deixarão, senão quando daí estejam banidos o orgulho e o egoísmo." "Predita foi a transformação da Humanidade e vos avizinhais do momento em que se dará, momento cuja chegada apressam todos os homens que auxiliam o progresso. Essa transformação se verificará por meio da encarnação de Espíritos melhores, que constituirão na Terra uma geração nova. Então, os Espíritos dos maus, que a morte vai ceifando dia a dia, e todos os que tentem deter a marcha das coisas serão daí excluídos, pois que viriam a estar deslocados entre os homens de bem, cuja felicidade perturbariam. Irão para mundos novos, menos adiantados, desempenhar missões penosas, trabalhando pelo seu próprio adiantamento, ao mesmo tempo que trabalharão pelo de seus irmãos ainda mais atrasados. Neste banimento de Espíritos da Terra transformada, não percebeis a sublime alegoria do Paraíso perdido e, na vinda do homem para a Terra em semelhantes condições, trazendo em si o gérmen de suas paixões e os vestígios da sua inferioridade primitiva, não descobris a não menos sublime alegoria do pecado original? Considerado deste ponto de vista, o pecado original se prende à natureza ainda imperfeita do homem que, assim, só é responsável por si mesmo, pelas suas próprias faltas e não pelas de seus pais." "Todos vós, homens de fé e de boa vontade, trabalhai, portanto, com ânimo e zelo na grande obra da regeneração, que colhereis pelo cêntuplo o grão que 326 – Allan Kar dec houverdes semeado. Ai dos que fecham os olhos à luz! Preparam para si mesmos longos séculos de trevas e decepções. Ai dos que fazem dos bens deste mundo a fonte de todas as suas alegrias! Terão que sofrer privações muito mais numerosas do que os gozos de que desfrutaram! Ai, sobretudo, dos egoístas! Não acharão quem os ajude a carregar o fardo de suas misérias.', 'rascunho')
